diff --git a/frontend/app/composables/__tests__/use-auth-backend.test.ts b/frontend/app/composables/__tests__/use-auth-backend.test.ts
new file mode 100644
index 0000000..8caf11f
--- /dev/null
+++ b/frontend/app/composables/__tests__/use-auth-backend.test.ts
@@ -0,0 +1,182 @@
+import { describe, expect, test, vi, beforeEach, afterEach } from "vitest";
+
+vi.mock("~/composables/store", () => ({ clearAllStores: vi.fn() }));
+vi.mock("~/composables/use-clear-composable-caches", () => ({ clearComposableCaches: vi.fn() }));
+
+const TOKEN_NAME = "mealie.access_token";
+
+function makeJwt(expSeconds: number) {
+  const payload = btoa(JSON.stringify({ exp: expSeconds })).replace(/=+$/, "");
+  return `h.${payload}.s`;
+}
+
+function clearCookie() {
+  document.cookie = `${TOKEN_NAME}=; Max-Age=0; Path=/`;
+}
+
+describe("useAuthBackend", () => {
+  let axios: { get: ReturnType<typeof vi.fn>; post: ReturnType<typeof vi.fn> };
+  let router: { push: ReturnType<typeof vi.fn> };
+
+  async function load() {
+    vi.resetModules();
+    const mod = await import("../use-auth-backend");
+    return mod.useAuthBackend();
+  }
+
+  beforeEach(() => {
+    clearCookie();
+    axios = { get: vi.fn(), post: vi.fn() };
+    router = { push: vi.fn().mockResolvedValue(undefined) };
+    vi.stubGlobal("useNuxtApp", () => ({ $axios: axios, $appInfo: { production: false, tokenTime: 48 } }));
+    vi.stubGlobal("useRouter", () => router);
+    vi.stubGlobal("useRuntimeConfig", () => ({ public: { AUTH_TOKEN: TOKEN_NAME } }));
+    vi.stubGlobal("clearNuxtData", vi.fn());
+    vi.stubGlobal("useCookie", (name: string) => ({
+      get value() {
+        return null;
+      },
+      set value(v: string | null) {
+        document.cookie = v ? `${name}=${v}; Path=/` : `${name}=; Max-Age=0; Path=/`;
+      },
+    }));
+    vi.spyOn(console, "error").mockImplementation(() => {});
+    vi.spyOn(console, "warn").mockImplementation(() => {});
+  });
+
+  afterEach(() => {
+    vi.useRealTimers();
+    vi.unstubAllGlobals();
+    vi.restoreAllMocks();
+    clearCookie();
+  });
+
+  test("setToken keeps the token in memory, shared, and null clears cookie and token", async () => {
+    const a = await load();
+    a.setToken("tok");
+    expect(a.token.value).toBe("tok");
+    expect(document.cookie).not.toContain("tok");
+
+    document.cookie = `${TOKEN_NAME}=old; Path=/`;
+    a.setToken(null);
+    expect(a.token.value).toBeNull();
+    expect(document.cookie).not.toContain(TOKEN_NAME);
+  });
+
+  test("setToken schedules a background refresh from exp", async () => {
+    vi.useFakeTimers();
+    const auth = await load();
+    axios.post.mockResolvedValue({ data: { access_token: "next" } });
+    auth.setToken(makeJwt(Math.floor(Date.now() / 1000) + 36000));
+
+    await vi.advanceTimersByTimeAsync(5 * 3600 * 1000);
+    expect(axios.post).not.toHaveBeenCalled();
+    await vi.advanceTimersByTimeAsync(2 * 3600 * 1000);
+    expect(axios.post).toHaveBeenCalledTimes(1);
+    expect(auth.token.value).toBe("next");
+  });
+
+  test("setToken(null) cancels the scheduled refresh", async () => {
+    vi.useFakeTimers();
+    const auth = await load();
+    auth.setToken(makeJwt(Math.floor(Date.now() / 1000) + 36000));
+    auth.setToken(null);
+    await vi.advanceTimersByTimeAsync(11 * 3600 * 1000);
+    expect(axios.post).not.toHaveBeenCalled();
+  });
+
+  test("refresh makes no request without a token", async () => {
+    const auth = await load();
+    await auth.refresh();
+    expect(axios.post).not.toHaveBeenCalled();
+  });
+
+  test("refresh posts once for concurrent calls and adopts the new token without fetching the user", async () => {
+    const auth = await load();
+    auth.setToken("old");
+    axios.post.mockResolvedValue({ data: { access_token: "new" } });
+
+    await Promise.all([auth.refresh(), auth.refresh(), auth.refresh()]);
+
+    expect(axios.post).toHaveBeenCalledTimes(1);
+    expect(axios.post).toHaveBeenCalledWith("/api/auth/refresh", null, { suppressAlert: true });
+    expect(auth.token.value).toBe("new");
+    expect(axios.get).not.toHaveBeenCalled();
+
+    await auth.refresh();
+    expect(axios.post).toHaveBeenCalledTimes(2);
+  });
+
+  test("refresh works from the token cookie alone", async () => {
+    document.cookie = `${TOKEN_NAME}=cookie; Path=/`;
+    const auth = await load();
+    axios.post.mockResolvedValue({ data: { access_token: "new" } });
+    await auth.refresh();
+    expect(axios.post).toHaveBeenCalledTimes(1);
+  });
+
+  test("a 401 clears the token, navigates to login and rejects; a new call retries", async () => {
+    const auth = await load();
+    auth.setToken("old");
+    const error = { response: { status: 401 } };
+    axios.post.mockRejectedValue(error);
+
+    const results = await Promise.allSettled([auth.refresh()]);
+    expect(results[0]).toMatchObject({ status: "rejected", reason: error });
+    expect(auth.token.value).toBeNull();
+    expect(router.push).toHaveBeenCalledWith("/login");
+
+    auth.setToken("again");
+    await expect(auth.refresh()).rejects.toBe(error);
+    expect(axios.post).toHaveBeenCalledTimes(2);
+  });
+
+  test("other errors reject but keep the token and do not navigate", async () => {
+    const auth = await load();
+    auth.setToken("keep");
+    const error = new Error("network");
+    axios.post.mockRejectedValue(error);
+
+    await expect(auth.refresh()).rejects.toBe(error);
+    await expect(auth.refresh()).rejects.toBe(error);
+    expect(axios.post).toHaveBeenCalledTimes(2);
+    expect(auth.token.value).toBe("keep");
+    expect(router.push).not.toHaveBeenCalled();
+  });
+
+  test("signIn keeps the token and loads the session", async () => {
+    const auth = await load();
+    axios.post.mockResolvedValue({ data: { access_token: "fresh" } });
+    axios.get.mockResolvedValue({ data: { id: "u1" } });
+
+    await auth.signIn(new FormData());
+
+    expect(auth.token.value).toBe("fresh");
+    expect(axios.get).toHaveBeenCalledWith("/api/users/self");
+    expect(auth.status.value).toBe("authenticated");
+    expect(auth.data.value).toEqual({ id: "u1" });
+  });
+
+  test("signIn rethrows rejected credentials without fetching the user", async () => {
+    const auth = await load();
+    const error = { response: { status: 401 } };
+    axios.post.mockRejectedValue(error);
+
+    await expect(auth.signIn(new FormData())).rejects.toBe(error);
+    expect(auth.status.value).toBe("unauthenticated");
+    expect(axios.get).not.toHaveBeenCalled();
+  });
+
+  test("signOut clears the token and navigates, even when logout fails", async () => {
+    const auth = await load();
+    auth.setToken("tok");
+    axios.post.mockRejectedValue({ response: { status: 401 } });
+
+    await auth.signOut("/recipes");
+    expect(auth.token.value).toBeNull();
+    expect(router.push).toHaveBeenCalledWith("/recipes");
+
+    await auth.signOut();
+    expect(router.push).toHaveBeenLastCalledWith("/login");
+  });
+});
