   Object.defineProperty(window, "location", {
@@ -79,3 +79,73 @@ describe("getTokenCookieOptions", () => {
     expect(options.partitioned).toBe(false);
   });
 });
+
+describe("getTokenCookieOptions maxAge", () => {
+  test("has no maxAge key", () => {
+    vi.stubGlobal("useNuxtApp", () => ({ $appInfo: { production: true, tokenTime: 48 } }));
+    expect("maxAge" in getTokenCookieOptions()).toBe(false);
+    vi.unstubAllGlobals();
+  });
+});
+
+function jwt(payload: object, pad = false) {
+  const b64 = btoa(JSON.stringify(payload)).replace(/\+/g, "-").replace(/\//g, "_");
+  return `h.${pad ? b64 : b64.replace(/=+$/, "")}.sig`;
+}
+
+describe("getTokenExpiry", () => {
+  test("reads exp in milliseconds, padded or not", () => {
+    expect(getTokenExpiry(jwt({ exp: 1 }))).toBe(1000);
+    expect(getTokenExpiry(jwt({ exp: 12 }, true))).toBe(12000);
+  });
+
+  test("returns null without exp or for malformed tokens", () => {
+    expect(getTokenExpiry(jwt({ sub: "x" }))).toBeNull();
+    expect(getTokenExpiry("not-a-jwt")).toBeNull();
+    expect(getTokenExpiry("header.@@@notbase64@@@.signature")).toBeNull();
+    expect(getTokenExpiry("")).toBeNull();
+  });
+});
+
+describe("readTokenCookie", () => {
+  afterEach(() => {
+    document.cookie = "mealie.access_token=; Max-Age=0; Path=/";
+    document.cookie = "other=; Max-Age=0; Path=/";
+  });
+
+  test("returns the URL-decoded value of exactly that cookie", () => {
+    document.cookie = `mealie.access_token=${encodeURIComponent("a.b+c/d")}; Path=/`;
+    document.cookie = "xmealie.access_token=wrong; Path=/";
+    expect(readTokenCookie("mealie.access_token")).toBe("a.b+c/d");
+    document.cookie = "xmealie.access_token=; Max-Age=0; Path=/";
+  });
+
+  test("returns null when absent even if others are set", () => {
+    document.cookie = "other=1; Path=/";
+    expect(readTokenCookie("mealie.access_token")).toBeNull();
+  });
+});
+
+describe("nextRefreshDelay", () => {
+  const HOUR = 3600 * 1000;
+  const CAP = 2147483647;
+
+  test("is 60% of remaining time with a floor and jitter", () => {
+    expect(nextRefreshDelay(10 * HOUR, 0)).toBe(6 * HOUR);
+    expect(nextRefreshDelay(10000, 0)).toBe(30000);
+    expect(nextRefreshDelay(10 * HOUR, 1)).toBe(6 * HOUR + 30000);
+    expect(nextRefreshDelay(10 * HOUR, 0.5)).toBe(6 * HOUR + 15000);
+  });
+
+  test("is capped at the largest timer delay", () => {
+    expect(nextRefreshDelay(400 * 24 * HOUR, 0)).toBe(CAP);
+    for (const remaining of [42 * 24 * HOUR, 400 * 24 * HOUR, Number.MAX_SAFE_INTEGER]) {
+      expect(nextRefreshDelay(remaining, 1)).toBeLessThanOrEqual(CAP);
+    }
+  });
+
+  test("is null for expired tokens", () => {
+    expect(nextRefreshDelay(0)).toBeNull();
+    expect(nextRefreshDelay(-5)).toBeNull();
+  });
+});
