diff --git a/frontend/app/composables/use-token-cookie.ts b/frontend/app/composables/use-token-cookie.ts
index b6acb5f..82b0b30 100644
--- a/frontend/app/composables/use-token-cookie.ts
+++ b/frontend/app/composables/use-token-cookie.ts
@@ -1,3 +1,9 @@
+const MAX_TIMEOUT_MS = 2147483647;
+const MIN_REFRESH_DELAY_MS = 30000;
+const REFRESH_JITTER_MS = 30000;
+
+// The server owns the cookie's lifetime (Max-Age), so no maxAge is returned here.
+// These options only need to match the server's attributes so the client can clear the cookie.
 export function getTokenCookieOptions() {
   const { $appInfo } = useNuxtApp();

@@ -5,9 +11,49 @@ export function getTokenCookieOptions() {
   const isEmbedded = isSecureConnection && window?.self !== window?.top;

   return {
-    maxAge: $appInfo.tokenTime * 60 * 60,
     secure: isSecureConnection,
     sameSite: (isEmbedded ? "none" : "lax") as "none" | "lax",
     partitioned: isEmbedded,
   };
 }
+
+/** Returns the JWT `exp` claim in epoch milliseconds, or null if it cannot be read. */
+export function getTokenExpiry(token: string): number | null {
+  try {
+    const payload = token.split(".")[1];
+    if (!payload) return null;
+
+    const base64 = payload.replace(/-/g, "+").replace(/_/g, "/");
+    const padded = base64 + "=".repeat((4 - (base64.length % 4)) % 4);
+    const claims = JSON.parse(atob(padded));
+
+    return typeof claims?.exp === "number" ? claims.exp * 1000 : null;
+  }
+  catch {
+    return null;
+  }
+}
+
+/** Returns the URL-decoded value of exactly the named cookie, or null when absent. */
+export function readTokenCookie(name: string): string | null {
+  for (const part of document.cookie.split(";")) {
+    const entry = part.trim();
+    const separator = entry.indexOf("=");
+    if (separator === -1 || entry.slice(0, separator) !== name) continue;
+
+    const raw = entry.slice(separator + 1);
+    try {
+      return decodeURIComponent(raw);
+    }
+    catch {
+      return raw;
+    }
+  }
+  return null;
+}
+
+/** Milliseconds to wait before refreshing a token with `remainingMs` left, or null if already expired. */
+export function nextRefreshDelay(remainingMs: number, jitter: number = Math.random()): number | null {
+  if (remainingMs <= 0) return null;
+  return Math.min(Math.max(remainingMs * 0.6, MIN_REFRESH_DELAY_MS) + jitter * REFRESH_JITTER_MS, MAX_TIMEOUT_MS);
+}
