index 0000000..9c4ac99
--- /dev/null
+++ b/frontend/app/plugins/__tests__/axios.test.ts
@@ -0,0 +1,153 @@
+import { describe, expect, test, vi, beforeEach, afterEach } from "vitest";
+import type { AxiosAdapter, AxiosInstance, InternalAxiosRequestConfig } from "axios";
+
+const TOKEN_NAME = "mealie.access_token";
+
+function clearCookie() {
+  document.cookie = `${TOKEN_NAME}=; Max-Age=0; Path=/`;
+}
+
+function reject401(config: InternalAxiosRequestConfig) {
+  return Promise.reject(Object.assign(new Error("401"), { config, response: { status: 401, data: {}, config } }));
+}
+
+function ok(config: InternalAxiosRequestConfig) {
+  return Promise.resolve({ data: { ok: true }, status: 200, statusText: "OK", headers: {}, config });
+}
+
+describe("axios plugin", () => {
+  let auth: { refresh: ReturnType<typeof vi.fn>; setToken: ReturnType<typeof vi.fn> };
+  let instance: AxiosInstance;
+  let calls: InternalAxiosRequestConfig[];
+  let hrefSetter: ReturnType<typeof vi.fn>;
+
+  async function setup(adapter: (c: InternalAxiosRequestConfig) => Promise<unknown>) {
+    vi.resetModules();
+    vi.stubGlobal("defineNuxtPlugin", (fn: unknown) => fn);
+    const mod = await import("../axios");
+    const result = (mod.default as unknown as (app: unknown) => { provide: { axios: AxiosInstance } })({
+      runWithContext: (fn: () => unknown) => fn(),
+    });
+    instance = result.provide.axios;
+    calls = [];
+    instance.defaults.adapter = ((config: InternalAxiosRequestConfig) => {
+      calls.push(config);
+      return adapter(config);
