+
 export default defineNuxtPlugin({
   async setup() {
     const auth = useAuthBackend();
+    const tokenName = useRuntimeConfig().public.AUTH_TOKEN;

     console.debug("Initializing auth plugin");
     await auth.getSession();
+
+    // Adopt the token cookie (another tab may have refreshed or ended the session) and
+    // re-arm the refresh timer, which browsers may have throttled while the tab was idle.
+    async function syncAndSchedule() {
+      const cookieToken = readTokenCookie(tokenName);
+      if (cookieToken) {
+        auth.setToken(cookieToken);
+        return;
+      }
+      if (auth.token.value) {
+        // The cookie is gone: signed out in another tab.
+        auth.setToken(null);
+        await auth.getSession();
+      }
+    }
+
+    const onVisible = () => {
+      if (document.visibilityState === "visible") syncAndSchedule();
+    };
+
+    if (auth.token.value) {
+      await syncAndSchedule();
+    }
+    window.addEventListener("focus", syncAndSchedule);
+    window.addEventListener("online", syncAndSchedule);
+    document.addEventListener("visibilitychange", onVisible);
+
+    // Follow cross-tab changes as they happen where the Cookie Store API exists.
+    const cookieStore = (window as any).cookieStore;
+    cookieStore?.addEventListener?.("change", (event: any) => {
+      const touched = [...(event.changed ?? []), ...(event.deleted ?? [])];
+      if (touched.some((c: { name: string }) => c.name === tokenName)) syncAndSchedule();
+    });
+
     console.debug("Auth plugin initialized");
   },
 });
