@@ -0,0 +1,24 @@
+from datetime import UTC, datetime, timedelta
+
+import jwt
+
+from mealie.core.config import get_app_settings
+
+ALGORITHM = "HS256"
+ISS = "mealie"
+
+
+def create_access_token(data: dict, expires_delta: timedelta | None = None) -> tuple[str, timedelta]:
+    """
+    Sign a JWT carrying `data` plus `iss`, `iat` and `exp`.
+
+    Returns the token and the lifetime it was granted (TOKEN_TIME hours unless `expires_delta` is given).
+    `iat` and `exp` are whole seconds, so `exp - iat` equals the lifetime in seconds exactly.
+    """
+    settings = get_app_settings()
+
+    lifetime = timedelta(hours=settings.TOKEN_TIME) if expires_delta is None else expires_delta
+    iat = int(datetime.now(UTC).timestamp())
+    claims = {**data, "iss": ISS, "iat": iat, "exp": iat + int(lifetime.total_seconds())}
+
+    return jwt.encode(claims, settings.SECRET, algorithm=ALGORITHM), lifetime
