+def session_cookie_attrs(request: Request) -> dict[str, Any]:
+    """Attributes of the session cookie; shared by setting and clearing it so both match exactly"""
+    forwarded_proto = request.headers.get("x-forwarded-proto", "").split(",")[0].strip().lower()
+    secure = request.url.scheme == "https" or forwarded_proto == "https"
+    embedded = request.headers.get("x-mealie-embedded", "").strip().lower() == "true"
+    cross_site = secure and embedded
+    return {
+        "secure": secure,
+        "samesite": "none" if cross_site else "lax",
+        "partitioned": cross_site,
+        "path": "/",
+        "httponly": False,  # the SPA reads the cookie to build its Authorization header
+    }
+
+
+def _set_cookie(response: Response, request: Request, **kwargs: Any) -> None:
+    """Set the session cookie with the attributes of `session_cookie_attrs`.
+
+    The standard library cookie module only knows `Partitioned` from Python 3.14, so the attribute
+    is appended to the header by hand; the rest is left to Starlette.
+    """
+    attrs = session_cookie_attrs(request)
+    partitioned = attrs.pop("partitioned")
+    response.set_cookie(COOKIE_NAME, **kwargs, **attrs)
+    if partitioned:
+        index = len(response.raw_headers) - 1
+        name, value = response.raw_headers[index]
+        response.raw_headers[index] = (name, value + b"; Partitioned")
+
+
+def set_session_cookie(response: Response, request: Request, token: str, lifetime: timedelta, remember: bool) -> None:
+    """Set the session cookie; it only outlives the browser session when `remember` is set"""
+    _set_cookie(response, request, value=token, max_age=int(lifetime.total_seconds()) if remember else None)
+
+
+def clear_session_cookie(response: Response, request: Request) -> None:
+    # not delete_cookie: it cannot send `partitioned`, so a partitioned cookie would not be cleared
+    _set_cookie(response, request, value="", max_age=0, expires=0)
