+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+
+def login(api_client: TestClient, user: TestUser, remember_me: bool):
+    api_client.cookies.clear()
+    return api_client.post(
+        api_routes.auth_token,
+        data={"username": user.email, "password": user.password, "remember_me": remember_me},
+    )
+
+
+def claims(token: str) -> dict:
+    return jwt.decode(token, get_app_settings().SECRET, algorithms=[ALGORITHM])
+
+
+@pytest.mark.parametrize("remember_me", [True, False])
+def test_refresh_keeps_rme_and_resets_cookie(api_client: TestClient, unique_user: TestUser, remember_me: bool):
+    body = login(api_client, unique_user, remember_me).json()
+    headers = {"Authorization": f"Bearer {body['access_token']}"}
+    api_client.cookies.clear()
+
+    response = api_client.post(api_routes.auth_refresh, headers=headers)
+    assert response.status_code == 200
+    data = response.json()
+    assert data["token_type"] == "bearer"
+    assert data["expires_in"] == get_app_settings().TOKEN_TIME * 3600
+
+    payload = claims(data["access_token"])
+    assert payload["rme"] is remember_me
+    assert payload["sub"] == str(unique_user.user_id)
+
+    cookie = response.headers.get_list("set-cookie")[0]
+    assert cookie.startswith(f"mealie.access_token={data['access_token']}")
+    assert ("Max-Age=" in cookie) is remember_me
+
+    me = api_client.get(api_routes.users_self, headers={"Authorization": f"Bearer {data['access_token']}"})
+    assert me.status_code == 200
+    assert me.json()["id"] == str(unique_user.user_id)
+
+
+def test_refresh_with_cookie_only(api_client: TestClient, unique_user: TestUser):
+    token = login(api_client, unique_user, False).json()["access_token"]
+    api_client.cookies.clear()
+    api_client.cookies.set("mealie.access_token", token)
+
+    try:
+        response = api_client.post(api_routes.auth_refresh)
+    finally:
+        api_client.cookies.clear()
+
+    assert response.status_code == 200
+
+
+def test_refresh_without_credential_is_401(api_client: TestClient):
+    api_client.cookies.clear()
+    assert api_client.post(api_routes.auth_refresh).status_code == 401
+
+
+def test_refresh_with_invalid_token_is_401(api_client: TestClient):
+    response = api_client.post(api_routes.auth_refresh, headers={"Authorization": "Bearer not-a-token"})
+    assert response.status_code == 401
+
+
+def test_refresh_rejects_api_token(api_client: TestClient, unique_user: TestUser):
+    created = api_client.post(api_routes.users_api_tokens, json={"name": "refresh"}, headers=unique_user.token)
+    assert created.status_code == 201
+
+    response = api_client.post(api_routes.auth_refresh, headers={"Authorization": f"Bearer {created.json()['token']}"})
