+def _bearer(token: str) -> dict:
+    return {"Authorization": f"Bearer {token}"}
+
+
+def test_password_change_ends_existing_sessions(api_client: TestClient, unique_user_fn_scoped: TestUser):
+    user = unique_user_fn_scoped
+    old_session = user.token["Authorization"].split(" ", 1)[1]
+    long_token = api_client.post(api_routes.users_api_tokens, json={"name": "survivor"}, headers=user.token)
+    assert long_token.status_code == 201
+
+    assert api_client.get(api_routes.users_self, headers=_bearer(old_session)).status_code == 200
+
+    new_password = random_string(15)
+    response = api_client.put(
+        api_routes.users_password,
+        json={"currentPassword": user.password, "newPassword": new_password},
+        headers=user.token,
+    )
+    assert response.status_code == 200
+
+    changed = user.repos.users.get_one(user.user_id)
+    assert changed is not None
+    assert changed.tokens_valid_after is not None
+    tva = int(changed.tokens_valid_after.replace(tzinfo=UTC).timestamp())
+    exp = int(datetime.now(UTC).timestamp()) + 3600
+    secret = get_app_settings().SECRET
+
+    def craft(**claims) -> dict:
+        return _bearer(jwt.encode({"sub": str(user.user_id), "exp": exp, **claims}, secret, algorithm=ALGORITHM))
+
+    # the pre-change session is dead, crafted tokens around the boundary behave
+    assert api_client.get(api_routes.users_self, headers=craft(iat=tva - 1)).status_code == 401
+    assert api_client.get(api_routes.users_self, headers=craft()).status_code == 401
+    assert api_client.get(api_routes.users_self, headers=craft(iat=tva)).status_code == 200
+
+    # logging in right after the change gives a working token
+    response = api_client.post(api_routes.auth_token, data={"username": user.email, "password": new_password})
+    assert response.status_code == 200
+    new_token = response.json()["access_token"]
+    assert api_client.get(api_routes.users_self, headers=_bearer(new_token)).status_code == 200
+
+    # API tokens created before the change are unaffected
+    api_token_headers = _bearer(long_token.json()["token"])
+    assert api_client.get(api_routes.users_self, headers=api_token_headers).status_code == 200
+
