+import asyncio
+from datetime import UTC, datetime, timedelta
+
+import jwt
+import pytest
+from fastapi import HTTPException
+from starlette.requests import Request
+
+from mealie.core.config import get_app_settings
+from mealie.core.dependencies.dependencies import _session_token_is_valid, get_auth_token
+from mealie.core.security import ALGORITHM, create_access_token
+from mealie.schema.user.user import PrivateUser
+from tests.utils.fixture_schemas import TestUser
+
+COOKIE = "mealie.access_token"
+
+
+def make_request(cookie: str | None = None) -> Request:
+    headers = []
+    if cookie is not None:
+        headers.append((b"cookie", cookie.encode()))
+    return Request({"type": "http", "method": "GET", "path": "/", "headers": headers})
+
+
+def run_get_auth_token(request: Request, token: str | None) -> str:
+    return asyncio.run(get_auth_token(request, token))
+
+
+@pytest.mark.parametrize(
+    ("header_token", "cookie", "expected"),
+    [
+        ("header-token", None, "header-token"),
+        (None, f"{COOKIE}=cookie-token", "cookie-token"),
+        ("header-token", f"{COOKIE}=cookie-token", "header-token"),
+        (None, None, ""),
+        (None, "other=value", ""),
+        (None, f"other=value; {COOKIE}=cookie-token", "cookie-token"),
+    ],
+)
+def test_get_auth_token(header_token: str | None, cookie: str | None, expected: str) -> None:
+    assert run_get_auth_token(make_request(cookie), header_token) == expected
+
+
+def test_get_auth_token_invalid_header_does_not_fall_back_to_cookie() -> None:
+    assert run_get_auth_token(make_request(f"{COOKIE}=good"), "garbage") == "garbage"
+
+
+def _user_with(valid_after: datetime | None) -> PrivateUser:
+    user = PrivateUser.model_construct(tokens_valid_after=valid_after)
+    return user
+
+
+# tokens_valid_after is naive UTC
+VALID_AFTER = datetime(2026, 6, 1, 12, 0, 0, 900_000, tzinfo=UTC).replace(tzinfo=None)
+VALID_AFTER_TS = int(VALID_AFTER.replace(tzinfo=UTC).timestamp())
+
+
+@pytest.mark.parametrize(
+    ("payload", "valid"),
+    [
+        ({"iat": VALID_AFTER_TS - 1}, False),
+        ({"iat": VALID_AFTER_TS}, True),  # same second as the change keeps working
+        ({"iat": VALID_AFTER_TS + 1}, True),
+        ({"iat": float(VALID_AFTER_TS)}, True),
+        ({}, False),
+        ({"iat": "123"}, False),
+        ({"iat": None}, False),
+        ({"iat": True}, False),
+    ],
+)
+def test_session_token_is_valid_with_tokens_valid_after(payload: dict, valid: bool) -> None:
+    assert _session_token_is_valid(payload, _user_with(VALID_AFTER)) is valid
+
+
+@pytest.mark.parametrize("payload", [{}, {"iat": 1}, {"iat": VALID_AFTER_TS}])
+def test_session_token_is_valid_without_tokens_valid_after(payload: dict) -> None:
+    assert _session_token_is_valid(payload, _user_with(None)) is True
+
+
+def _encode(claims: dict) -> str:
+    settings = get_app_settings()
+    return jwt.encode(claims, settings.SECRET, algorithm=ALGORITHM)
+
+
+def test_get_current_user_honours_tokens_valid_after(unique_user_fn_scoped: TestUser, api_client) -> None:
+    from mealie.core.security import hash_password
+    from tests.utils import api_routes
+
+    user = unique_user_fn_scoped
+    changed = user.repos.users.update_password(user.user_id, hash_password("a-brand-new-password"))
+    assert changed.tokens_valid_after is not None
+    tva = int(changed.tokens_valid_after.replace(tzinfo=UTC).timestamp())
+    exp = int((datetime.now(UTC) + timedelta(hours=1)).timestamp())
+
+    def get_self(claims: dict | None):
+        headers = {"Authorization": f"Bearer {_encode(claims)}"} if claims is not None else {}
+        return api_client.get(api_routes.users_self, headers=headers)
+
+    sub = {"sub": str(user.user_id), "exp": exp}
+    assert get_self({**sub, "iat": tva - 1}).status_code == 401
+    assert get_self(sub).status_code == 401
+    assert get_self({**sub, "iat": tva}).status_code == 200
+
+
+def test_file_token_without_file_claim_is_401() -> None:
+    from mealie.core.dependencies import validate_file_token
+
+    session_token, _ = create_access_token({"sub": "someone"})
+    with pytest.raises(HTTPException) as exc:
+        validate_file_token(session_token)
+    assert exc.value.status_code == 401
diff --git a/tests/unit_tests/core/test_session_cookie.py b/tests/unit_tests/core/test_session_cookie.py
