@@ -0,0 +1,99 @@
+from datetime import timedelta
+
+import pytest
+from starlette.requests import Request
+from starlette.responses import Response
+
+from mealie.routes.auth import auth as auth_routes
+from mealie.routes.auth.auth import (
+    COOKIE_NAME,
+    clear_session_cookie,
+    session_cookie_attrs,
+    set_session_cookie,
+)
+
+
+def make_request(scheme: str = "http", headers: dict[str, str] | None = None) -> Request:
+    raw_headers = [(k.lower().encode(), v.encode()) for k, v in (headers or {}).items()]
+    scope = {
+        "type": "http",
+        "method": "POST",
+        "scheme": scheme,
+        "path": "/api/auth/token",
+        "query_string": b"",
+        "headers": raw_headers,
+        "server": ("testserver", 80),
+    }
+    return Request(scope)
+
+
+@pytest.mark.parametrize(
+    ("scheme", "headers", "secure", "samesite", "partitioned"),
+    [
+        ("https", {}, True, "lax", False),
+        ("http", {}, False, "lax", False),
+        ("http", {"X-Forwarded-Proto": "https"}, True, "lax", False),
+        ("http", {"X-Forwarded-Proto": "https, http"}, True, "lax", False),
+        ("http", {"X-Forwarded-Proto": " HTTPS "}, True, "lax", False),
+        ("http", {"X-Forwarded-Proto": "http, https"}, False, "lax", False),
+        ("https", {"X-Mealie-Embedded": "true"}, True, "none", True),
+        ("http", {"X-Mealie-Embedded": "true", "X-Forwarded-Proto": "https"}, True, "none", True),
+        ("http", {"X-Mealie-Embedded": "true"}, False, "lax", False),
+        ("https", {"X-Mealie-Embedded": "false"}, True, "lax", False),
+    ],
+)
+def test_session_cookie_attrs(scheme, headers, secure, samesite, partitioned):
+    attrs = session_cookie_attrs(make_request(scheme, headers))
+
+    assert attrs["secure"] is secure
+    assert attrs["samesite"] == samesite
+    assert attrs["partitioned"] is partitioned
+    assert attrs["path"] == "/"
+    assert attrs["httponly"] is False
+
+
+def cookie_header(response: Response) -> str:
+    cookies = response.headers.getlist("set-cookie")
+    assert len(cookies) == 1
+    return cookies[0]
+
+
+def test_set_session_cookie_remember_has_max_age():
+    response = Response()
+    set_session_cookie(response, make_request(), "tok", timedelta(hours=2), remember=True)
+
+    header = cookie_header(response)
+    assert header.startswith(f"{COOKIE_NAME}=tok")
+    assert "Max-Age=7200" in header
+    assert "Path=/" in header
+    assert "httponly" not in header.lower()
+
+
+def test_set_session_cookie_without_remember_is_session_cookie():
+    response = Response()
+    set_session_cookie(response, make_request(), "tok", timedelta(hours=2), remember=False)
+
+    assert "max-age" not in cookie_header(response).lower()
+
+
+def test_clear_session_cookie_matches_set_attributes_and_expires():
+    request = make_request("https", {"X-Mealie-Embedded": "true"})
+    set_response, clear_response = Response(), Response()
+    set_session_cookie(set_response, request, "tok", timedelta(hours=1), remember=True)
+    clear_session_cookie(clear_response, request)
+
+    cleared = cookie_header(clear_response)
+    assert cleared.startswith(f"{COOKIE_NAME}=;") or cleared.startswith(f'{COOKIE_NAME}="";')
+    assert "Max-Age=0" in cleared
+    for attr in ("partitioned", "secure", "samesite=none", "path=/"):
+        assert attr in cleared.lower()
+        assert attr in cookie_header(set_response).lower()
+
+
+def test_clear_session_cookie_does_not_use_delete_cookie(monkeypatch: pytest.MonkeyPatch):
+    def fail(*args, **kwargs):
+        raise AssertionError("delete_cookie cannot send Partitioned")
+
+    monkeypatch.setattr(Response, "delete_cookie", fail)
+    clear_session_cookie(Response(), make_request())
+    assert auth_routes.COOKIE_NAME == "mealie.access_token"
