+
+def test_new_user_has_no_tokens_valid_after(unique_user_fn_scoped: TestUser) -> None:
+    user = unique_user_fn_scoped.repos.users.get_one(unique_user_fn_scoped.user_id)
+    assert user is not None
+    assert user.tokens_valid_after is None
+
+
+def test_update_password_sets_tokens_valid_after(unique_user_fn_scoped: TestUser) -> None:
+    repos = unique_user_fn_scoped.repos
+    updated = repos.users.update_password(unique_user_fn_scoped.user_id, hash_password("a-new-password"))
+
+    assert updated.tokens_valid_after is not None
+    stored = repos.users.get_one(unique_user_fn_scoped.user_id)
+    assert stored is not None
+    assert stored.tokens_valid_after == updated.tokens_valid_after
+
+
+def test_stale_profile_update_does_not_overwrite_tokens_valid_after(unique_user_fn_scoped: TestUser) -> None:
+    repos = unique_user_fn_scoped.repos
+    stale = repos.users.get_one(unique_user_fn_scoped.user_id)
+    assert isinstance(stale, PrivateUser)
+    assert stale.tokens_valid_after is None
+
+    changed = repos.users.update_password(unique_user_fn_scoped.user_id, hash_password("another-password"))
+    assert changed.tokens_valid_after is not None
+
+    # profile update from a copy loaded before the password change, via model and via dict
+    stale.full_name = "Renamed User"
+    repos.users.update(stale.id, stale)
+    repos.users.update(stale.id, stale.model_dump())
+
+    stored = repos.users.get_one(unique_user_fn_scoped.user_id)
+    assert stored is not None
+    assert stored.full_name == "Renamed User"
+    assert stored.tokens_valid_after == changed.tokens_valid_after
