+const TOKEN_NAME = "mealie.auth.token";
+
+const refresh = vi.fn();
+const setToken = vi.fn();
+
+type Handler = (config: InternalAxiosRequestConfig) => { status: number; data?: unknown };
+
+async function loadAxios(handler: Handler) {
+  vi.stubGlobal("defineNuxtPlugin", (setup: (app: unknown) => { provide: { axios: AxiosInstance } }) => setup);
+  vi.stubGlobal("useRuntimeConfig", () => ({ public: { AUTH_TOKEN: TOKEN_NAME } }));
+  vi.stubGlobal("useAuthBackend", () => ({ refresh, setToken }));
