+  const setup = mod.default as unknown as (app: unknown) => { provide: { axios: AxiosInstance } };
+  const app = { runWithContext: <T>(fn: () => T) => fn() };
+  const instance = setup(app).provide.axios;
+
+  const seen: InternalAxiosRequestConfig[] = [];
+  instance.defaults.adapter = async (config) => {
+    seen.push(config);
+    const { status, data } = handler(config);
+    const response = { data: data ?? {}, status, statusText: "", headers: {}, config };
+    if (status >= 400) {
+      throw new AxiosError("failed", undefined, config, null, response);
+    }
+    return response;
+  };
+  return { instance, seen };
