+  afterEach(() => {
+    vi.unstubAllGlobals();
+    setCookie(null);
+    setFramed(false);
+  });
+
+  test("sends the cookie token at send time and no embedded header when not framed", async () => {
+    const { instance, seen } = await loadAxios(() => ({ status: 200 }));
