+  });
+
+  test("sets X-Mealie-Embedded when framed", async () => {
+    setFramed(true);
+    const { instance, seen } = await loadAxios(() => ({ status: 200 }));
+    await instance.get("/api/foo");
+    expect(seen[0]!.headers["X-Mealie-Embedded"]).toBe("true");
+  });
+
+  test("401 refreshes once and replays with the new cookie token", async () => {
