+    refresh.mockImplementation(async () => setCookie("new"));
+    const { instance, seen } = await loadAxios(config =>
+      config.headers.Authorization === "Bearer new" ? { status: 200, data: { ok: true } } : { status: 401 },
+    );
+
+    const response = await instance.get("/api/foo");
+
+    expect(response.data).toEqual({ ok: true });
+    expect(refresh).toHaveBeenCalledTimes(1);
+    expect(seen).toHaveLength(2);
+    expect(setToken).not.toHaveBeenCalled();
+    expect(window.location.href).toBe("");
+  });
+
+  test("an endpoint that always answers 401 refreshes once, then ends the session", async () => {
+    setCookie("old");
+    refresh.mockResolvedValue(undefined);
+    const { instance, seen } = await loadAxios(() => ({ status: 401 }));
+
+    await expect(instance.get("/api/foo")).rejects.toMatchObject({ response: { status: 401 } });
+
+    expect(refresh).toHaveBeenCalledTimes(1);
+    expect(seen).toHaveLength(2);
+    expect(setToken).toHaveBeenCalledWith(null);
+    expect(window.location.href).toBe("/login?redirect=%2Fg%2Fhome%2Fr%2Fsoup");
+  });
+
+  test("a failed refresh ends the session without replaying", async () => {
+    setCookie("old");
+    refresh.mockRejectedValue(new Error("nope"));
+    const { instance, seen } = await loadAxios(() => ({ status: 401 }));
+
+    await expect(instance.get("/api/foo")).rejects.toMatchObject({ response: { status: 401 } });
+
+    expect(seen).toHaveLength(1);
+    expect(setToken).toHaveBeenCalledWith(null);
+    expect(window.location.href).toBe("/login?redirect=%2Fg%2Fhome%2Fr%2Fsoup");
+  });
+
+  test("a non-401 error on the replay rejects as itself without ending the session", async () => {
+    setCookie("old");
+    refresh.mockResolvedValue(undefined);
+    let calls = 0;
+    const { instance } = await loadAxios(() => ({ status: ++calls === 1 ? 401 : 500 }));
+
+    await expect(instance.get("/api/foo")).rejects.toMatchObject({ response: { status: 500 } });
+
+    expect(setToken).not.toHaveBeenCalled();
+    expect(window.location.href).toBe("");
+  });
+
+  test.each(["/api/auth/token", "/api/auth/refresh"])("401 from %s never refreshes", async (url) => {
+    setCookie("old");
+    const { instance, seen } = await loadAxios(() => ({ status: 401 }));
+
+    await expect(instance.post(url)).rejects.toMatchObject({ response: { status: 401 } });
+
+    expect(refresh).not.toHaveBeenCalled();
+    expect(seen).toHaveLength(1);
+  });
+
+  test("401 from logout neither refreshes nor redirects", async () => {
+    setCookie("old");
+    const { instance } = await loadAxios(() => ({ status: 401 }));
+
+    await expect(instance.post("/api/auth/logout")).rejects.toMatchObject({ response: { status: 401 } });
+
+    expect(refresh).not.toHaveBeenCalled();
+    expect(setToken).not.toHaveBeenCalled();
+    expect(window.location.href).toBe("");
+  });
+
+  test("401 without a token cookie just rejects", async () => {
+    const { instance, seen } = await loadAxios(() => ({ status: 401 }));
+
+    await expect(instance.get("/api/foo")).rejects.toMatchObject({ response: { status: 401 } });
+
+    expect(refresh).not.toHaveBeenCalled();
+    expect(setToken).not.toHaveBeenCalled();
+    expect(seen[0]!.headers.Authorization).toBeUndefined();
+    expect(window.location.href).toBe("");
+  });
+});
