--- /dev/null
+++ b/mealie/core/security/tokens.py
@@ -0,0 +1,28 @@
+from datetime import UTC, datetime, timedelta
+
+import jwt
+
+from mealie.core.config import get_app_settings
+
+ISS = "mealie"
+ALGORITHM = "HS256"
+
+
+def create_access_token(data: dict, expires_delta: timedelta | None = None) -> tuple[str, timedelta]:
+    """
+    Signs a JWT carrying `data` plus `iss`, `iat` and `exp`.
+
+    Returns the token and the lifetime it was granted. `iat` is truncated to whole seconds so that
+    `exp - iat` equals the lifetime exactly.
+    """
+    settings = get_app_settings()
+
+    lifetime = expires_delta or timedelta(hours=settings.TOKEN_TIME)
+    now = datetime.now(UTC).replace(microsecond=0)
+
+    to_encode = data.copy()
+    to_encode["iss"] = ISS
+    to_encode["iat"] = now
+    to_encode["exp"] = now + lifetime
+
+    return jwt.encode(to_encode, settings.SECRET, algorithm=ALGORITHM), lifetime
