diff --git a/tests/integration_tests/user_tests/test_user_session_cookie.py b/tests/integration_tests/user_tests/test_user_session_cookie.py
new file mode 100644
index 0000000..a155b3a
--- /dev/null
+++ b/tests/integration_tests/user_tests/test_user_session_cookie.py
@@ -0,0 +1,123 @@
+import jwt
+import pytest
+from fastapi.testclient import TestClient
+
+from mealie.core.config import get_app_settings
+from mealie.core.security import ALGORITHM
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+COOKIE = "mealie.access_token"
+
+
+def login(api_client: TestClient, user: TestUser, remember_me: bool, headers: dict | None = None):
+    form = {"username": user.email, "password": user.password, "remember_me": str(remember_me).lower()}
+    return api_client.post(api_routes.auth_token, data=form, headers=headers or {})
+
+
+def claims(token: str) -> dict:
+    return jwt.decode(token, get_app_settings().SECRET, algorithms=[ALGORITHM])
+
+
+def first_cookie(response) -> str:
+    return response.headers.get_list("set-cookie")[0]
+
+
+@pytest.mark.parametrize("remember_me", [True, False])
+def test_login_body_and_cookie(api_client: TestClient, unique_user: TestUser, remember_me: bool):
+    response = login(api_client, unique_user, remember_me)
+    assert response.status_code == 200
+    body = response.json()
+    expected = get_app_settings().TOKEN_TIME * 3600
+
+    assert body["token_type"] == "bearer"
+    assert body["expires_in"] == expected
+    payload = claims(body["access_token"])
+    assert payload["rme"] is remember_me
+    assert payload["exp"] - payload["iat"] == expected
+
+    cookie = first_cookie(response)
+    assert cookie.startswith(f"{COOKIE}={body['access_token']}")
+    assert "Path=/" in cookie
+    assert "httponly" not in cookie.lower()
+    assert ("Max-Age=" + str(expected) in cookie) is remember_me
+    assert ("Max-Age" in cookie) is remember_me
+
+
+def test_login_cookie_embedded_attributes(api_client: TestClient, unique_user: TestUser):
+    headers = {"X-Forwarded-Proto": "https", "X-Mealie-Embedded": "true"}
+    cookie = first_cookie(login(api_client, unique_user, False, headers))
+
+    assert "SameSite=None" in cookie
+    assert "Secure" in cookie
+    assert "Partitioned" in cookie
+
+
+def test_login_failure_sets_no_cookie(api_client: TestClient, unique_user: TestUser):
+    response = api_client.post(api_routes.auth_token, data={"username": unique_user.email, "password": "nope"})
+    assert response.status_code == 401
+    assert "set-cookie" not in response.headers
+
+
+@pytest.mark.parametrize("remember_me", [True, False])
+def test_refresh_keeps_rme(api_client: TestClient, unique_user: TestUser, remember_me: bool):
+    token = login(api_client, unique_user, remember_me).json()["access_token"]
+    headers = {"Authorization": f"Bearer {token}"}
+
+    response = api_client.post(api_routes.auth_refresh, headers=headers)
+    assert response.status_code == 200
+    body = response.json()
+    assert body["token_type"] == "bearer"
+    assert body["expires_in"] == get_app_settings().TOKEN_TIME * 3600
+    assert claims(body["access_token"])["rme"] is remember_me
+
+    cookie = first_cookie(response)
+    assert cookie.startswith(f"{COOKIE}={body['access_token']}")
+    assert ("Max-Age=" in cookie) is remember_me
+
+    me = api_client.get(api_routes.users_self, headers={"Authorization": f"Bearer {body['access_token']}"})
+    assert me.status_code == 200
+    assert me.json()["id"] == str(unique_user.user_id)
+
+
+def test_refresh_requires_post_and_credential(api_client: TestClient):
+    api_client.cookies.clear()  # earlier logins on the shared client leave the session cookie in its jar
+    assert api_client.get(api_routes.auth_refresh).status_code == 405
+    assert api_client.post(api_routes.auth_refresh).status_code == 401
+    assert api_client.post(api_routes.auth_refresh, headers={"Authorization": "Bearer nonsense"}).status_code == 401
+
+
+def test_refresh_refuses_api_token(api_client: TestClient, unique_user: TestUser):
+    created = api_client.post(api_routes.users_api_tokens, json={"name": "t"}, headers=unique_user.token)
+    assert created.status_code == 201
+    api_token = created.json()["token"]
+
+    response = api_client.post(api_routes.auth_refresh, headers={"Authorization": f"Bearer {api_token}"})
+    assert response.status_code == 400
+
+
+@pytest.mark.parametrize(
+    ("headers", "expected"),
+    [
+        ({}, ["SameSite=Lax"]),
+        ({"X-Forwarded-Proto": "https"}, ["SameSite=Lax", "Secure"]),
+        ({"X-Forwarded-Proto": "https", "X-Mealie-Embedded": "true"}, ["SameSite=None", "Secure", "Partitioned"]),
+    ],
+)
+def test_logout_clears_cookie_with_same_attributes(
+    api_client: TestClient, unique_user: TestUser, headers: dict, expected: list[str]
+):
+    token = login(api_client, unique_user, True, headers).json()["access_token"]
+    set_cookie = first_cookie(login(api_client, unique_user, True, headers))
+
+    response = api_client.post(api_routes.auth_logout, headers={"Authorization": f"Bearer {token}", **headers})
+    assert response.status_code == 200
+    assert "message" in response.json()
+
+    cleared = first_cookie(response)
+    assert cleared.startswith(f"{COOKIE}=;")
+    assert "Max-Age=0" in cleared
+    for attr in expected:
+        assert attr in cleared
+        assert attr in set_cookie
+    assert ("Partitioned" in cleared) == ("Partitioned" in set_cookie)
diff --git a/tests/integration_tests/user_tests/test_user_session_invalidation.py b/tests/integration_tests/user_tests/test_user_session_invalidation.py
new file mode 100644
index 0000000..88dfc59
--- /dev/null
+++ b/tests/integration_tests/user_tests/test_user_session_invalidation.py
@@ -0,0 +1,217 @@
+from collections.abc import Generator
+from datetime import UTC, datetime, timedelta
+
+import jwt
+import pytest
+from fastapi.testclient import TestClient
+from sqlalchemy import text
+from sqlalchemy.orm import Session
+
+from mealie.core.config import get_app_settings
+from mealie.core.security import ALGORITHM
+from mealie.db.models._model_utils.datetime import get_utc_now
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+NEW_PASSWORD = "a-brand-new-password-1"
+
+
+def _bearer(token: str) -> dict:
+    return {"Authorization": f"Bearer {token}"}
+
+
+def _session_token(user: TestUser, iat: datetime | None, **extra) -> str:
+    """Signs a session token by hand so tests control `iat` without sleeping."""
+    claims: dict = {"sub": str(user.user_id), "exp": get_utc_now() + timedelta(hours=1), **extra}
+    if iat is not None:
+        claims["iat"] = iat
+    return jwt.encode(claims, get_app_settings().SECRET, algorithm=ALGORITHM)
+
+
+def _login(api_client: TestClient, user: TestUser, password: str):
+    return api_client.post(api_routes.auth_token, data={"username": user.email, "password": password})
+
+
+def _stamp(session: Session, user: TestUser) -> datetime | None:
+    session.expire_all()
+    value = session.execute(
+        text("SELECT tokens_valid_after FROM users WHERE id = :id"), {"id": user.user_id.hex}
+    ).scalar_one()
+    if isinstance(value, str):
+        value = datetime.fromisoformat(value)
+    return value
+
+
+def _set_stamp(session: Session, user: TestUser, value: datetime | None) -> None:
+    session.execute(
+        text("UPDATE users SET tokens_valid_after = :v WHERE id = :id"),
+        {"v": value.replace(tzinfo=None) if value else None, "id": user.user_id.hex},
+    )
+    session.commit()
+
+
+@pytest.fixture
+def user(unique_user_fn_scoped: TestUser, api_client: TestClient) -> Generator[TestUser, None, None]:
+    # the shared client keeps the session cookie of earlier logins; cookie fallback would hide expected 401s
+    api_client.cookies.clear()
+    yield unique_user_fn_scoped
+    api_client.cookies.clear()
+
+
+def _change_password_via_api(api_client: TestClient, user: TestUser, headers: dict):
+    response = api_client.put(
+        api_routes.users_password,
+        json={"currentPassword": user.password, "newPassword": NEW_PASSWORD},
+        headers=headers,
+    )
+    api_client.cookies.clear()
+    return response
+
+
+def test_password_change_invalidates_earlier_session_token(api_client: TestClient, user: TestUser, session: Session):
+    past = get_utc_now() - timedelta(minutes=5)
+    old = _bearer(_session_token(user, past, rme=False))
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 200  # NULL stamp: unaffected
+
+    current = _bearer(_session_token(user, get_utc_now()))
+    response = _change_password_via_api(api_client, user, current)
+    assert response.status_code == 200
+    assert _stamp(session, user) is not None
+
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+
+
+def test_login_with_new_password_works_after_change(api_client: TestClient, user: TestUser):
+    assert _change_password_via_api(api_client, user, _bearer(_session_token(user, get_utc_now()))).status_code == 200
+
+    assert _login(api_client, user, user.password).status_code == 401
+    response = _login(api_client, user, NEW_PASSWORD)
+    assert response.status_code == 200
+
+    api_client.cookies.clear()
+    assert api_client.get(api_routes.users_self, headers=_bearer(response.json()["access_token"])).status_code == 200
+
+
+def test_api_token_survives_password_change(api_client: TestClient, user: TestUser):
+    response = api_client.post(api_routes.users_api_tokens, json={"name": "survivor"}, headers=user.token)
+    assert response.status_code == 201
+    api_token = _bearer(response.json()["token"])
+    api_client.cookies.clear()
+    assert api_client.get(api_routes.users_self, headers=api_token).status_code == 200
+
+    assert _change_password_via_api(api_client, user, user.token).status_code == 200
+
+    assert api_client.get(api_routes.users_self, headers=api_token).status_code == 200
+
+
+def test_pre_change_token_from_login_is_rejected_after_change(api_client: TestClient, user: TestUser, session: Session):
+    """A real login token, then a change whose stamp lies after that token's issue second."""
+    response = _login(api_client, user, user.password)
+    assert response.status_code == 200
+    old = _bearer(response.json()["access_token"])
+    api_client.cookies.clear()
+
+    _set_stamp(session, user, get_utc_now() + timedelta(seconds=5))
+
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+
+
+def test_token_without_iat_rejected_once_stamped(api_client: TestClient, user: TestUser, session: Session):
+    legacy = _bearer(_session_token(user, None))
+    assert api_client.get(api_routes.users_self, headers=legacy).status_code == 200
+
+    assert _change_password_via_api(api_client, user, user.token).status_code == 200
+
+    assert api_client.get(api_routes.users_self, headers=legacy).status_code == 401
+
+
+def test_non_numeric_iat_rejected_once_stamped(api_client: TestClient, user: TestUser, session: Session):
+    _set_stamp(session, user, get_utc_now())
+    bad = jwt.encode(
+        {"sub": str(user.user_id), "iat": "yesterday", "exp": get_utc_now() + timedelta(hours=1)},
+        get_app_settings().SECRET,
+        algorithm=ALGORITHM,
+    )
+    assert api_client.get(api_routes.users_self, headers=_bearer(bad)).status_code == 401
+
+
+def test_same_second_and_later_tokens_keep_working(api_client: TestClient, user: TestUser, session: Session):
+    # a mid-second stamp in the past (an iat in the future is rejected by the JWT library itself)
+    cutoff = (datetime.now(UTC) - timedelta(seconds=10)).replace(microsecond=500_000)
+    _set_stamp(session, user, cutoff)
+    whole = cutoff.replace(microsecond=0)
+
+    same_second = _bearer(_session_token(user, whole))
+    later = _bearer(_session_token(user, whole + timedelta(seconds=5)))
+    earlier = _bearer(_session_token(user, whole - timedelta(seconds=1)))
+
+    assert api_client.get(api_routes.users_self, headers=same_second).status_code == 200
+    assert api_client.get(api_routes.users_self, headers=later).status_code == 200
+    assert api_client.get(api_routes.users_self, headers=earlier).status_code == 401
+
+
+def test_null_stamp_accepts_tokens_with_and_without_iat(api_client: TestClient, user: TestUser, session: Session):
+    assert _stamp(session, user) is None
+
+    for iat in (None, get_utc_now() - timedelta(days=1)):
+        token = _bearer(_session_token(user, iat))
+        assert api_client.get(api_routes.users_self, headers=token).status_code == 200
+
+
+def test_invalidated_token_cannot_be_refreshed(api_client: TestClient, user: TestUser, session: Session):
+    old = _bearer(_session_token(user, get_utc_now() - timedelta(minutes=5), rme=True))
+    _set_stamp(session, user, get_utc_now())
+
+    assert api_client.post(api_routes.auth_refresh, headers=old).status_code == 401
+
+
+def test_stale_cookie_does_not_authenticate_after_change(api_client: TestClient, user: TestUser, session: Session):
+    """The cookie fallback must honour the cutoff too."""
+    old = _session_token(user, get_utc_now() - timedelta(minutes=5))
+    _set_stamp(session, user, get_utc_now())
+
+    api_client.cookies.clear()
+    api_client.cookies.set("mealie.access_token", old)
+    try:
+        assert api_client.get(api_routes.users_self).status_code == 401
+    finally:
+        api_client.cookies.clear()
+
+
+def test_password_reset_flow_ends_sessions(api_client: TestClient, user: TestUser, session: Session):
+    from mealie.db.db_setup import session_context
+    from mealie.services.user_services.password_reset_service import PasswordResetService
+
+    old = _bearer(_session_token(user, get_utc_now() - timedelta(minutes=5)))
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 200
+
+    with session_context() as db_session:
+        token = PasswordResetService(db_session).generate_reset_token(user.email)
+        assert token is not None
+
+    payload = {
+        "token": token.token,
+        "email": user.email,
+        "password": NEW_PASSWORD,
+        "passwordConfirm": NEW_PASSWORD,
+    }
+    assert api_client.post(api_routes.users_reset_password, json=payload).status_code == 200
+    assert _stamp(session, user) is not None
+
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+    response = _login(api_client, user, NEW_PASSWORD)
+    assert response.status_code == 200
+    api_client.cookies.clear()
+    assert api_client.get(api_routes.users_self, headers=_bearer(response.json()["access_token"])).status_code == 200
+
+
+def test_failed_password_change_does_not_stamp(api_client: TestClient, user: TestUser, session: Session):
+    response = api_client.put(
+        api_routes.users_password,
+        json={"currentPassword": "wrong-current", "newPassword": NEW_PASSWORD},
+        headers=user.token,
+    )
+    api_client.cookies.clear()
+    assert response.status_code == 400
+    assert _stamp(session, user) is None
+    assert api_client.get(api_routes.users_self, headers=user.token).status_code == 200
