+        "sub": str(user.user_id),
+        "iat": get_utc_now() - timedelta(minutes=5),
+        "exp": get_utc_now() + timedelta(hours=1),
+    }
+    return {"Authorization": f"Bearer {jwt.encode(claims, get_app_settings().SECRET, algorithm=ALGORITHM)}"}
+
+
+def _stamp(user: TestUser) -> datetime | None:
+    stored = user.repos.users.get_one(user.user_id)
