+
+    users.update_password(user.user_id, hash_password(NEW_PASSWORD))
+    stamp = _stamp(user)
+    assert stamp is not None
+
+    users.update(user.user_id, stale)
+
+    assert _stamp(user) == stamp
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+
+
+def test_stale_dict_write_back_keeps_stamp(api_client: TestClient, user: TestUser):
+    users = user.repos.users
+    old = _old_token(user)
+    stale = users.get_one(user.user_id)
+    assert stale is not None
+
+    users.update_password(user.user_id, hash_password(NEW_PASSWORD))
+    stamp = _stamp(user)
+
+    for bogus in (None, datetime(2000, 1, 1, tzinfo=UTC)):
+        users.update(user.user_id, {**stale.model_dump(), "tokens_valid_after": bogus})
+        assert _stamp(user) == stamp
+
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+
+
+def test_explicit_value_on_private_user_never_changes_stored_stamp(user: TestUser):
+    users = user.repos.users
+    current = users.get_one(user.user_id)
+    assert current is not None
+
+    users.update(user.user_id, current.model_copy(update={"tokens_valid_after": get_utc_now()}))
+
+    assert _stamp(user) is None
+
+
+def test_login_after_password_change_does_not_clear_stamp(api_client: TestClient, user: TestUser):
+    """Login runs users.update with a freshly loaded PrivateUser; it must leave the stamp alone."""
+    user.repos.users.update_password(user.user_id, hash_password(NEW_PASSWORD))
+    stamp = _stamp(user)
+    assert stamp is not None
+    old = _old_token(user)
+
+    response = api_client.post(api_routes.auth_token, data={"username": user.email, "password": NEW_PASSWORD})
+    assert response.status_code == 200
+    api_client.cookies.clear()
+
+    assert _stamp(user) == stamp
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+    token = {"Authorization": f"Bearer {response.json()['access_token']}"}
+    assert api_client.get(api_routes.users_self, headers=token).status_code == 200
+
+
+def test_change_password_script_stamps_and_survives_auth_method_reset(
+    api_client: TestClient, user: TestUser, monkeypatch: pytest.MonkeyPatch
+):
+    """The script writes back the pre-stamp user when it resets the auth method; the stamp must survive."""
+    user.repos.users.patch(user.user_id, {"auth_method": AuthMethod.OIDC})
+    old = _old_token(user)
+    assert _stamp(user) is None
+
+    answers = iter([user.email, "y", ""])  # email, reset auth method, "press enter to exit"
+    monkeypatch.setattr("builtins.input", lambda *_: next(answers))
+    monkeypatch.setattr(change_password, "getpass", lambda *_: NEW_PASSWORD)
+
+    with pytest.raises(SystemExit) as exit_info:
+        change_password.main()
+    assert exit_info.value.code == 0
+
+    stored = user.repos.users.get_one(user.user_id)
+    assert stored is not None
+    assert stored.auth_method == AuthMethod.MEALIE
+    assert stored.tokens_valid_after is not None
+
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+    response = api_client.post(api_routes.auth_token, data={"username": user.email, "password": NEW_PASSWORD})
+    assert response.status_code == 200
+
+
+def test_change_password_script_without_auth_method_reset_stamps(
+    api_client: TestClient, user: TestUser, monkeypatch: pytest.MonkeyPatch
+):
+    old = _old_token(user)
+    answers = iter([user.email, ""])
+    monkeypatch.setattr("builtins.input", lambda *_: next(answers))
+    monkeypatch.setattr(change_password, "getpass", lambda *_: NEW_PASSWORD)
+
+    with pytest.raises(SystemExit) as exit_info:
+        change_password.main()
+    assert exit_info.value.code == 0
+
+    assert _stamp(user) is not None
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
