+import time
+from datetime import timedelta
+
+import jwt
+import pytest
+from fastapi.testclient import TestClient
+from sqlalchemy import text
+
+from mealie.core.config import get_app_settings
+from mealie.core.security import ALGORITHM, create_access_token
+from mealie.db.models._model_utils.datetime import get_utc_now
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+
+def _set_valid_after(session, user: TestUser, value) -> None:
+    session.execute(
+        text("UPDATE users SET tokens_valid_after = :v WHERE id = :id"),
+        {"v": value, "id": user.user_id.hex},
+    )
+    session.commit()
+
+
+def _bearer(token: str) -> dict:
+    return {"Authorization": f"Bearer {token}"}
+
+
+@pytest.fixture
+def user(unique_user_fn_scoped: TestUser):
+    return unique_user_fn_scoped
+
+
+def test_old_token_rejected_after_cutoff(api_client: TestClient, user: TestUser, session):
+    token, _ = create_access_token({"sub": str(user.user_id), "rme": False})
+    assert api_client.get(api_routes.users_self, headers=_bearer(token)).status_code == 200
+
+    _set_valid_after(session, user, (get_utc_now() + timedelta(seconds=30)).replace(tzinfo=None))
+
+    assert api_client.get(api_routes.users_self, headers=_bearer(token)).status_code == 401
+
+
+def test_token_issued_in_cutoff_second_keeps_working(api_client: TestClient, user: TestUser, session):
+    token, _ = create_access_token({"sub": str(user.user_id)})
+    # the cutoff is later within the same whole second as the token's iat
+    _set_valid_after(session, user, get_utc_now().replace(tzinfo=None))
+
+    assert api_client.get(api_routes.users_self, headers=_bearer(token)).status_code == 200
+
+
+def test_token_without_iat_rejected_when_cutoff_set(api_client: TestClient, user: TestUser, session):
+    legacy = jwt.encode({"sub": str(user.user_id)}, get_app_settings().SECRET, algorithm=ALGORITHM)
+    assert api_client.get(api_routes.users_self, headers=_bearer(legacy)).status_code == 200
+
+    _set_valid_after(session, user, get_utc_now().replace(tzinfo=None))
+
+    assert api_client.get(api_routes.users_self, headers=_bearer(legacy)).status_code == 401
+
+
+def test_password_change_ends_sessions_but_not_api_tokens(api_client: TestClient, user: TestUser):
+    response = api_client.post(api_routes.auth_token, data={"username": user.email, "password": user.password})
+    assert response.status_code == 200
+    old = _bearer(response.json()["access_token"])
+
+    response = api_client.post(api_routes.users_api_tokens, json={"name": "survivor"}, headers=old)
+    assert response.status_code == 201
+    api_token = _bearer(response.json()["token"])
+
+    time.sleep(1.1)  # iat and the cutoff are compared in whole seconds
+    new_password = "a-brand-new-password"
+    response = api_client.put(
+        api_routes.users_password,
+        json={"currentPassword": user.password, "newPassword": new_password},
+        headers=old,
+    )
+    assert response.status_code == 200
+
+    assert api_client.get(api_routes.users_self, headers=old).status_code == 401
+    assert api_client.get(api_routes.users_self, headers=api_token).status_code == 200
+
+    response = api_client.post(api_routes.auth_token, data={"username": user.email, "password": new_password})
+    assert response.status_code == 200
+    assert api_client.get(api_routes.users_self, headers=_bearer(response.json()["access_token"])).status_code == 200
