@@ -0,0 +1,100 @@
+import asyncio
+from datetime import timedelta
+from pathlib import Path
+
+import jwt
+import pytest
+from fastapi import HTTPException
+from starlette.requests import Request
+
+from mealie.core.config import get_app_settings
+from mealie.core.dependencies import validate_file_token
+from mealie.core.dependencies.dependencies import get_auth_token
+from mealie.core.security import ALGORITHM, ISS, create_access_token, create_file_token
+from mealie.core.security.providers.credentials_provider import CredentialsProvider
+from mealie.schema.user.user import PrivateUser
+
+
+def _decode(token: str) -> dict:
+    return jwt.decode(token, get_app_settings().SECRET, algorithms=[ALGORITHM])
+
+
+def test_constants() -> None:
+    assert ISS == "mealie"
+    assert ALGORITHM == "HS256"
+
+
+def test_default_lifetime_and_claims() -> None:
+    data = {"sub": "abc"}
+    token, lifetime = create_access_token(data)
+
+    assert lifetime == timedelta(hours=get_app_settings().TOKEN_TIME)
+    assert data == {"sub": "abc"}  # not mutated
+
+    payload = _decode(token)
+    assert payload["sub"] == "abc"
+    assert payload["iss"] == ISS
+    assert isinstance(payload["iat"], int)
+    assert payload["exp"] - payload["iat"] == int(lifetime.total_seconds())
+
+
+def test_explicit_lifetime() -> None:
+    token, lifetime = create_access_token({"x": 1}, timedelta(minutes=5))
+
+    assert lifetime == timedelta(minutes=5)
+    payload = _decode(token)
+    assert payload["exp"] - payload["iat"] == 300
+
+
+def test_file_token_round_trip(tmp_path: Path) -> None:
+    file_path = tmp_path / "file.txt"
+    file_path.write_text("x")
+
+    token = create_file_token(file_path)
+    assert isinstance(token, str)
+    assert validate_file_token(token) == file_path
+
+    payload = _decode(token)
+    assert payload["iss"] == ISS
+    assert payload["exp"] - payload["iat"] == 30 * 60
+
+
+def test_validate_file_token_without_file_claim_is_401() -> None:
+    token, _ = create_access_token({"sub": "abc"})
+
+    with pytest.raises(HTTPException) as exc:
+        validate_file_token(token)
+
+    assert exc.value.status_code == 401
+
+
+def test_access_token_records_remember_me_without_changing_lifetime(unique_user) -> None:
+    user = unique_user.repos.users.get_one(unique_user.user_id)
+    assert isinstance(user, PrivateUser)
+    provider = CredentialsProvider.__new__(CredentialsProvider)
+
+    for remember in (True, False):
+        token, lifetime = provider.get_access_token(user, remember)
+        payload = _decode(token)
+        assert payload["rme"] is remember
+        assert payload["sub"] == str(user.id)
+        assert lifetime == timedelta(hours=get_app_settings().TOKEN_TIME)
+        assert payload["exp"] - payload["iat"] == int(lifetime.total_seconds())
+
+
+def _request(cookies: str | None = None) -> Request:
+    headers = [(b"cookie", cookies.encode())] if cookies else []
+    return Request({"type": "http", "headers": headers})
+
+
+@pytest.mark.parametrize(
+    ("header_token", "cookie", "expected"),
+    [
+        ("hdr", "mealie.access_token=ck", "hdr"),
+        (None, "mealie.access_token=ck", "ck"),
+        (None, None, ""),
+        (None, "other=ck", ""),
+    ],
+)
+def test_get_auth_token(header_token: str | None, cookie: str | None, expected: str) -> None:
+    assert asyncio.run(get_auth_token(_request(cookie), header_token)) == expected
