+from datetime import UTC, datetime, timedelta
+
+from mealie.db.models._model_utils.datetime import get_utc_now
+from tests.utils.fixture_schemas import TestUser
+
+OLD = datetime(2000, 1, 1, tzinfo=UTC)
+
+
+def _stamp(unique_user: TestUser) -> datetime | None:
+    user = unique_user.repos.users.get_one(unique_user.user_id)
+    assert user is not None
+    return user.tokens_valid_after
+
+
+def test_update_password_stamps_column(unique_user: TestUser) -> None:
+    before = get_utc_now() - timedelta(seconds=1)
+    unique_user.repos.users.update_password(unique_user.user_id, "new-hash")
+
+    stamp = _stamp(unique_user)
+    assert stamp is not None
+    assert stamp.replace(tzinfo=stamp.tzinfo or UTC) >= before
+
+
+def test_stale_private_user_update_does_not_clear_stamp(unique_user: TestUser) -> None:
+    users = unique_user.repos.users
+    stale = users.get_one(unique_user.user_id)
+    assert stale is not None
+    stale = stale.model_copy(update={"tokens_valid_after": None})
+
+    users.update_password(unique_user.user_id, "new-hash")
+    stamp = _stamp(unique_user)
+    assert stamp is not None
+
+    users.update(unique_user.user_id, stale)
+
+    assert _stamp(unique_user) == stamp
+
+
+def test_update_ignores_tokens_valid_after_in_private_user_and_dict(unique_user: TestUser) -> None:
+    users = unique_user.repos.users
+    unique_user.repos.users.update_password(unique_user.user_id, "new-hash")
+    stamp = _stamp(unique_user)
+    user = users.get_one(unique_user.user_id)
+    assert user is not None
+
+    users.update(unique_user.user_id, user.model_copy(update={"tokens_valid_after": OLD}))
+    assert _stamp(unique_user) == stamp
+
+    users.update(unique_user.user_id, {**user.model_dump(), "tokens_valid_after": None})
+    assert _stamp(unique_user) == stamp
+
+
+def test_model_update_ignores_tokens_valid_after(unique_user: TestUser) -> None:
+    users = unique_user.repos.users
+    users.update_password(unique_user.user_id, "new-hash")
+    stamp = _stamp(unique_user)
+    user = users.get_one(unique_user.user_id)
+    assert user is not None
+
+    entry = users._query_one(match_value=unique_user.user_id)
+    entry.update(session=users.session, **{**user.model_dump(), "tokens_valid_after": datetime(2000, 1, 1)})
+    users.session.commit()
+
+    assert _stamp(unique_user) == stamp
