+
+
+def test_every_naive_datetime_column_is_restored_as_datetime() -> None:
+    names = {
+        column.name
+        for table in SqlAlchemyBase.metadata.tables.values()
+        for column in table.columns
+        if isinstance(column.type, NaiveDateTime)
+    }
