+def clean_duration(time_entry: typing.Any) -> int | None:
+    """Read a time as a whole number of seconds, or None when it is not one clear duration.
+
+    Numbers and bare numeric strings are minutes; other strings must be ISO 8601 durations
+    without years or months (which have no fixed length). `timedelta`, `{"minValue": ...}`
+    and the first item of a list are read too. Results must be within 1..MAX_SECONDS.
+    """
+    seconds: Decimal
+    match time_entry:
+        case bool():
+            return None
+        case int() | float():
+            if isinstance(time_entry, float) and not math.isfinite(time_entry):
+                return None
+            seconds = Decimal(str(time_entry)) * 60
+        case str():
+            text = time_entry.strip()
+            if MATCH_BARE_NUMBER.match(text):
+                seconds = Decimal(text) * 60
+            else:
+                m = MATCH_DURATION.match(text)
+                if m is None or m.group("y") or m.group("mo"):
+                    return None
+                seconds = (
+                    Decimal(m.group("w") or 0) * 604800
+                    + Decimal(m.group("d") or 0) * 86400
+                    + Decimal(m.group("h") or 0) * 3600
+                    + Decimal(m.group("mi") or 0) * 60
+                    + Decimal(m.group("s") or 0)
+                )
+        case timedelta():
+            seconds = (
+                Decimal(time_entry.days) * 86400
+                + Decimal(time_entry.seconds)
+                + Decimal(time_entry.microseconds) / 1000000
+            )
+        case {"minValue": value}:
+            return clean_duration(value)
+        case [first, *_]:
+            return clean_duration(first)
+        case _:
+            return None
+
+    if not 0 < seconds <= MAX_SECONDS:  # also keeps quantize within Decimal's precision
+        return None
+
+    whole = int(seconds.quantize(Decimal(1), rounding=ROUND_HALF_UP))
+    return whole if 0 < whole <= MAX_SECONDS else None
+
