+def _old_recipes_table(metadata: sa.MetaData) -> sa.Table:
+    return sa.Table(
+        "recipes",
+        metadata,
+        sa.Column("id", GUID(), primary_key=True),
+        sa.Column("name", sa.String()),
+        sa.Column("total_time", sa.String()),
+        sa.Column("prep_time", sa.String()),
+        sa.Column("perform_time", sa.String()),
+        sa.Column("cook_time", sa.String()),
+    )
+
+
+@pytest.fixture
+def conn() -> Iterator[sa.Connection]:
+    engine = sa.create_engine("sqlite://")
+    with engine.connect() as connection:
+        _old_recipes_table(sa.MetaData()).create(connection)
+        yield connection
+    engine.dispose()
+
+
+def _run(migration_fn, connection: sa.Connection) -> None:
+    context = MigrationContext.configure(connection)
+    with Operations.context(context):
+        migration_fn()
+
+
+def _columns(connection: sa.Connection) -> set[str]:
+    return {c["name"] for c in sa.inspect(connection).get_columns("recipes")}
+
+
+def _insert(connection: sa.Connection, **times) -> UUID:
+    table = _old_recipes_table(sa.MetaData())
+    recipe_id = uuid4()
+    connection.execute(table.insert().values(id=recipe_id, name="r", **times))
+    return recipe_id
+
+
+def _fetch(connection: sa.Connection, recipe_id: UUID) -> dict:
+    row = connection.execute(sa.text("SELECT * FROM recipes WHERE id = :id"), {"id": f"{recipe_id.int:032x}"}).one()
+    return dict(row._mapping)
+
+
+def test_upgrade_adds_columns_and_converts_rows(migration: ModuleType, conn: sa.Connection):
+    converted = _insert(conn, total_time="1 hour 30 minutes", prep_time="PT20M", perform_time="45", cook_time="PT10M")
+    mixed = _insert(conn, total_time="overnight", prep_time="None", perform_time="1 hour and 10 minutes")
+    zero = _insert(conn, total_time="0", prep_time="PT0M", perform_time="  none ")
+    untouched = _insert(conn, total_time=None, prep_time=None, perform_time=None, cook_time="soon")
+    empty_string = _insert(conn, total_time="", prep_time="P1M", perform_time="30 mins")
+
+    _run(migration.upgrade, conn)
+
+    assert {"total_time_seconds", "prep_time_seconds", "perform_time_seconds"} <= _columns(conn)
+    assert "cook_time_seconds" not in _columns(conn)
+
+    row = _fetch(conn, converted)
+    assert (row["total_time"], row["total_time_seconds"]) == (None, 5400)
+    assert (row["prep_time"], row["prep_time_seconds"]) == (None, 1200)
+    assert (row["perform_time"], row["perform_time_seconds"]) == (None, 2700)
+    assert row["cook_time"] == "PT10M"  # cook_time is never touched
+
+    row = _fetch(conn, mixed)
+    assert (row["total_time"], row["total_time_seconds"]) == ("overnight", None)
+    assert (row["prep_time"], row["prep_time_seconds"]) == (None, None)  # "None" placeholder cleared
+    assert (row["perform_time"], row["perform_time_seconds"]) == ("1 hour and 10 minutes", None)
+
+    # zero durations are not seconds and not erased: only the literal "none" is dropped
+    row = _fetch(conn, zero)
+    assert (row["total_time"], row["total_time_seconds"]) == ("0", None)
+    assert (row["prep_time"], row["prep_time_seconds"]) == ("PT0M", None)
+    assert (row["perform_time"], row["perform_time_seconds"]) == (None, None)
+
+    row = _fetch(conn, untouched)
+    assert row["total_time"] is None and row["total_time_seconds"] is None
+    assert row["cook_time"] == "soon"
+
+    row = _fetch(conn, empty_string)
+    assert (row["total_time"], row["total_time_seconds"]) == ("", None)
+    assert (row["prep_time"], row["prep_time_seconds"]) == ("P1M", None)
+    assert (row["perform_time"], row["perform_time_seconds"]) == ("30 mins", None)
+
+
+def test_upgrade_on_empty_table(migration: ModuleType, conn: sa.Connection):
+    _run(migration.upgrade, conn)
+    assert "total_time_seconds" in _columns(conn)
+
