+def test_upgrade_converts_more_rows_than_one_batch(migration: ModuleType, conn: sa.Connection):
+    ids = [_insert(conn, total_time="PT1H") for _ in range(migration.BATCH_SIZE + 5)]
+
+    _run(migration.upgrade, conn)
+
+    count = conn.execute(sa.text("SELECT COUNT(*) FROM recipes WHERE total_time_seconds = 3600")).scalar()
+    assert count == len(ids)
+    assert conn.execute(sa.text("SELECT COUNT(*) FROM recipes WHERE total_time IS NOT NULL")).scalar() == 0
+
+
+def test_downgrade_restores_text_and_drops_columns(migration: ModuleType, conn: sa.Connection):
+    converted = _insert(conn, total_time="1 hour 30 minutes", prep_time="PT20M", perform_time="overnight")
+    _run(migration.upgrade, conn)
+
+    # a row with both text and seconds keeps its text
+    both = _insert(conn, total_time="about an hour")
+    conn.execute(sa.text("UPDATE recipes SET total_time_seconds = 60 WHERE id = :id"), {"id": f"{both.int:032x}"})
+    # hand-written zero seconds must not produce an empty string
+    zero = _insert(conn)
+    conn.execute(sa.text("UPDATE recipes SET prep_time_seconds = 0 WHERE id = :id"), {"id": f"{zero.int:032x}"})
+
+    _run(migration.downgrade, conn)
+
+    assert _columns(conn) == {"id", "name", "total_time", "prep_time", "perform_time", "cook_time"}
+
+    row = _fetch(conn, converted)
+    assert row["total_time"] == "1 hour 30 minutes"
+    assert row["prep_time"] == "20 minutes"
+    assert row["perform_time"] == "overnight"
+    assert row["cook_time"] is None
+
+    assert _fetch(conn, both)["total_time"] == "about an hour"
+    assert _fetch(conn, zero)["prep_time"] is None
+
+
+def test_upgrade_downgrade_upgrade_is_stable(migration: ModuleType, conn: sa.Connection):
+    recipe_id = _insert(conn, total_time="2 hours", prep_time="PT5M", perform_time="1 day")
+
+    _run(migration.upgrade, conn)
+    first = _fetch(conn, recipe_id)
+    _run(migration.downgrade, conn)
+    _run(migration.upgrade, conn)
+
+    assert _fetch(conn, recipe_id) == first
+    assert first["total_time_seconds"] == 7200
+    assert first["prep_time_seconds"] == 300
+    assert first["perform_time_seconds"] == 86400

