+import { flushPromises, mount, type VueWrapper } from "@vue/test-utils";
+import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
+import GroupAIPromptEditor from "./GroupAIPromptEditor.vue";
+import type { AIPromptsOut } from "~/lib/api/types/group";
+
+const wrappers: VueWrapper[] = [];
+
+const mocks = vi.hoisted(() => ({
+  prompts: null as { value: unknown } | null,
+  refresh: vi.fn(),
+  save: vi.fn(),
+  reset: vi.fn(),
+}));
+
+vi.mock("~/composables/use-ai-providers", () => ({
+  useAIPrompts: () => ({
+    prompts: mocks.prompts,
+    loading: ref(false),
+    refresh: mocks.refresh,
+    save: mocks.save,
+    reset: mocks.reset,
+  }),
+}));
+
+vi.mock("~/composables/use-toast", () => ({
+  alert: { success: vi.fn(), error: vi.fn() },
+}));
+
+function response(overrides: Partial<AIPromptsOut> = {}): AIPromptsOut {
+  return {
+    globalInstructions: null,
+    prompts: [
+      { name: "recipes.build-recipe", isSystem: false, defaultContent: "BUILD DEFAULT", mode: null, content: null, defaultChanged: false },
+      { name: "recipes.translate-recipe", isSystem: false, defaultContent: "TRANSLATE DEFAULT", mode: "override", content: "My prompt", defaultChanged: false },
+      { name: "system.compile-source", isSystem: true, defaultContent: "COMPILE DEFAULT", mode: "append", content: "Extra", defaultChanged: false },
+    ],
+    ...overrides,
+  };
+}
+
+const BtnToggle = {
+  props: ["modelValue"],
+  emits: ["update:modelValue"],
+  template: "<div class=\"toggle\" :data-mode=\"modelValue\"><slot /></div>",
+};
+
+function mountEditor(data: AIPromptsOut = response()) {
+  mocks.prompts = ref(data);
+  const wrapper = mount(GroupAIPromptEditor, {
+    global: {
+      mocks: { $globals: { icons: { alert: "alert" } } },
+      stubs: {
+        BaseButton: { props: ["save"], template: "<button class=\"save\" type=\"button\" />" },
+        VTextarea: {
+          props: ["modelValue", "readonly"],
+          emits: ["update:modelValue"],
+          template: "<textarea :value=\"modelValue\" @input=\"$emit('update:modelValue', $event.target.value)\" />",
+        },
+        VBtnToggle: BtnToggle,
+        VBtn: { props: ["value"], template: "<button type=\"button\"><slot /></button>" },
+        VExpansionPanels: { template: "<div><slot /></div>" },
+        VExpansionPanel: { template: "<div class=\"panel\"><slot /></div>" },
+        VExpansionPanelTitle: { template: "<div><slot /></div>" },
+        VExpansionPanelText: { template: "<div><slot /></div>" },
+        VIcon: { template: "<i><slot /></i>" },
+      },
+    },
+  });
+  wrappers.push(wrapper);
+  return wrapper;
+}
+
+function saveButtons(wrapper: VueWrapper) {
+  return wrapper.findAll("button.save");
+}
+
+describe("groupAIPromptEditor", () => {
+  beforeEach(() => {
+    mocks.refresh.mockReset().mockResolvedValue(null);
+    mocks.save.mockReset().mockResolvedValue(response());
+    mocks.reset.mockReset().mockResolvedValue(response());
+    vi.stubGlobal("useNuxtApp", () => ({ $globals: { icons: { alert: "alert" } } }));
+  });
+
+  afterEach(() => {
+    wrappers.forEach(wrapper => wrapper.unmount());
+    wrappers.length = 0;
+    vi.unstubAllGlobals();
+  });
+
+  test("prompts open in their saved mode and content", () => {
+    const wrapper = mountEditor();
+    const modes = wrapper.findAll(".toggle").map(toggle => toggle.attributes("data-mode"));
+    expect(modes).toEqual(["default", "override", "append"]);
+
+    const textareas = wrapper.findAll("textarea");
+    // group-wide, override editor, append editor (none for the default-mode prompt)
+    expect(textareas).toHaveLength(3);
+    expect((textareas[1]!.element as HTMLTextAreaElement).value).toBe("My prompt");
+    expect((textareas[2]!.element as HTMLTextAreaElement).value).toBe("Extra");
+  });
+
+  test("switching to override fills an empty editor with the built-in text but keeps existing text", async () => {
+    const wrapper = mountEditor();
+    const toggles = wrapper.findAllComponents(BtnToggle);
+
+    await toggles[0]!.vm.$emit("update:modelValue", "override");
+    await flushPromises();
+    expect((wrapper.findAll("textarea")[1]!.element as HTMLTextAreaElement).value).toBe("BUILD DEFAULT");
+
+    // the translate prompt is an override: switch to append and back, its text survives
+    await toggles[1]!.vm.$emit("update:modelValue", "append");
+    await flushPromises();
+    await toggles[1]!.vm.$emit("update:modelValue", "override");
+    await flushPromises();
+    const values = wrapper.findAll("textarea").map(t => (t.element as HTMLTextAreaElement).value);
+    expect(values).toContain("My prompt");
+  });
+
+  test("saving sends only the editor's text for the current mode", async () => {
+    const wrapper = mountEditor();
+    await saveButtons(wrapper)[3]!.trigger("click"); // system.compile-source, append
+    await flushPromises();
+    expect(mocks.save).toHaveBeenCalledWith("system.compile-source", { mode: "append", content: "Extra" });
+    expect(mocks.reset).not.toHaveBeenCalled();
+  });
+
+  test("saving in default mode resets the prompt", async () => {
+    const wrapper = mountEditor();
+    await saveButtons(wrapper)[1]!.trigger("click");
+    await flushPromises();
+    expect(mocks.reset).toHaveBeenCalledWith("recipes.build-recipe");
+    expect(mocks.save).not.toHaveBeenCalled();
+  });
+
+  test("group-wide instructions are trimmed, and reset when empty", async () => {
+    const wrapper = mountEditor();
+    const textarea = wrapper.findAll("textarea")[0]!;
+
+    await textarea.setValue("  use metric  ");
+    await saveButtons(wrapper)[0]!.trigger("click");
+    await flushPromises();
+    expect(mocks.save).toHaveBeenCalledWith("global", { mode: "append", content: "use metric" });
+
+    await textarea.setValue("   ");
+    await saveButtons(wrapper)[0]!.trigger("click");
+    await flushPromises();
+    expect(mocks.reset).toHaveBeenCalledWith("global");
+  });
+
+  test("a failed save keeps the user's mode and text", async () => {
+    mocks.save.mockResolvedValue(null);
+    const wrapper = mountEditor();
+
+    await wrapper.findAll("textarea")[1]!.setValue("Edited");
+    await saveButtons(wrapper)[2]!.trigger("click");
+    await flushPromises();
+
+    expect(mocks.save).toHaveBeenCalled();
+    expect((wrapper.findAll("textarea")[1]!.element as HTMLTextAreaElement).value).toBe("Edited");
+    expect(wrapper.findAll(".toggle")[1]!.attributes("data-mode")).toBe("override");
+  });
+});
