+    <p class="text-body-2 mb-3">
+      {{ $t("group.ai-prompts.prompts-description") }}
+    </p>
+    <v-expansion-panels variant="accordion">
+      <v-expansion-panel v-for="prompt in promptList" :key="prompt.name">
+        <v-expansion-panel-title>
+          <span class="font-weight-medium">{{ prompt.name }}</span>
+          <span v-if="prompt.isSystem" class="text-caption ms-2">{{ $t("group.ai-prompts.system-prompt") }}</span>
+          <span v-if="states[prompt.name]?.mode !== 'default'" class="text-caption ms-2">
+            ({{ $t(`group.ai-prompts.mode-${states[prompt.name]?.mode}`) }})
+          </span>
+          <v-icon v-if="prompt.defaultChanged" class="ms-2" size="small" color="warning">
+            {{ $globals.icons.alert }}
+          </v-icon>
+        </v-expansion-panel-title>
+        <v-expansion-panel-text>
+          <p v-if="prompt.isSystem" class="text-body-2 mb-2">
+            {{ $t("group.ai-prompts.system-prompt-description") }}
+          </p>
+          <p v-if="prompt.defaultChanged" class="text-body-2 mb-2 text-warning">
+            {{ $t("group.ai-prompts.default-changed") }}
+          </p>
+
+          <v-btn-toggle
+            :model-value="states[prompt.name]?.mode"
+            mandatory
+            density="compact"
+            color="primary"
+            class="mb-3"
+            @update:model-value="(mode: PromptMode | null | undefined) => setMode(prompt, mode)"
+          >
+            <v-btn value="default">
+              {{ $t("group.ai-prompts.mode-default") }}
+            </v-btn>
+            <v-btn value="append">
+              {{ $t("group.ai-prompts.mode-append") }}
+            </v-btn>
+            <v-btn value="override">
+              {{ $t("group.ai-prompts.mode-override") }}
+            </v-btn>
+          </v-btn-toggle>
+
+          <template v-if="states[prompt.name]">
+            <v-textarea
+              v-if="states[prompt.name]!.mode === 'append'"
+              v-model="states[prompt.name]!.appendText"
+              :label="$t('group.ai-prompts.additional-instructions')"
+              auto-grow
+              rows="3"
+              variant="outlined"
+              density="compact"
+              hide-details
+            />
+            <v-textarea
+              v-else-if="states[prompt.name]!.mode === 'override'"
+              v-model="states[prompt.name]!.overrideText"
+              :label="$t('group.ai-prompts.custom-prompt')"
+              auto-grow
+              rows="8"
+              variant="outlined"
+              density="compact"
+              hide-details
+            />
+
+            <div v-if="states[prompt.name]!.mode !== 'override'" class="mt-3">
+              <div class="text-caption">
+                {{ $t("group.ai-prompts.built-in-prompt") }}
+              </div>
+              <pre class="text-body-2" style="white-space: pre-wrap;">{{ prompt.defaultContent }}</pre>
+            </div>
+          </template>
+
+          <div class="d-flex justify-end mt-2">
+            <BaseButton save :loading="loading" @click="savePrompt(prompt)" />
+          </div>
+        </v-expansion-panel-text>
+      </v-expansion-panel>
+    </v-expansion-panels>
+  </div>
+</template>
+
+<script setup lang="ts">
+import { useAIPrompts } from "~/composables/use-ai-providers";
+import { alert } from "~/composables/use-toast";
+import type { AIPromptOut, AIPromptsOut } from "~/lib/api/types/group";
+
+type PromptMode = "default" | "append" | "override";
+
+interface PromptState {
+  mode: PromptMode;
+  appendText: string;
+  overrideText: string;
+  // what is stored on the server, used to tell when a refreshed response carries a new saved state
+  saved: string;
+}
+
+const props = defineProps<{
+  groupId?: string;
+}>();
+
+const i18n = useI18n();
+const { prompts, loading, refresh, save, reset } = useAIPrompts(props.groupId);
+
+const globalText = ref("");
+const savedGlobalText = ref<string | null>(null);
+const states = reactive<Record<string, PromptState>>({});
+
+const promptList = computed<AIPromptOut[]>(() => prompts.value?.prompts ?? []);
+
+function savedKey(mode: string | null | undefined, content: string | null | undefined) {
+  return JSON.stringify([mode ?? null, content ?? null]);
+}
+
+function buildState(prompt: AIPromptOut): PromptState {
+  return {
+    mode: prompt.mode ?? "default",
+    appendText: prompt.mode === "append" ? (prompt.content ?? "") : "",
+    overrideText: prompt.mode === "override" ? (prompt.content ?? "") : "",
+    saved: savedKey(prompt.mode, prompt.content),
+  };
+}
+
+// Builds the editor state from the prompts. Prompts the user is editing keep their unsaved changes,
+// unless the server's saved version of that prompt is not the one the edits started from.
+function syncPrompts(data: AIPromptsOut | null) {
+  if (!data) {
+    return;
+  }
+
+  for (const prompt of data.prompts) {
+    const current = states[prompt.name];
+    if (!current || current.saved !== savedKey(prompt.mode, prompt.content)) {
+      states[prompt.name] = buildState(prompt);
+    }
+  }
+
+  const savedGlobal = data.globalInstructions ?? "";
+  if (savedGlobal !== savedGlobalText.value) {
+    savedGlobalText.value = savedGlobal;
+    globalText.value = savedGlobal;
+  }
+}
+
+watch(prompts, syncPrompts, { immediate: true });
+
+onMounted(() => {
+  refresh();
+});
+
+function setMode(prompt: AIPromptOut, mode: PromptMode | null | undefined) {
+  const state = states[prompt.name];
+  if (!state || !mode) {
+    return;
+  }
+
+  state.mode = mode;
+  if (mode === "override" && !state.overrideText) {
+    state.overrideText = prompt.defaultContent;
+  }
+}
+
+async function saveGlobal() {
+  const content = globalText.value.trim();
+  const result = content ? await save("global", { mode: "append", content }) : await reset("global");
+
+  if (!result) {
+    alert.error(i18n.t("group.ai-prompts.save-failed"));
+    return;
+  }
+
+  globalText.value = content;
+  savedGlobalText.value = content;
+  alert.success(i18n.t("group.ai-prompts.saved"));
+}
+
+async function savePrompt(prompt: AIPromptOut) {
+  const state = states[prompt.name];
+  if (!state) {
+    return;
+  }
+
+  const mode = state.mode;
+  const content = mode === "append" ? state.appendText : state.overrideText;
+  const result = mode === "default" ? await reset(prompt.name) : await save(prompt.name, { mode, content });
+
+  if (!result) {
