+
+/**
+ * Prompt customizations of the current user's group, or of `groupId` (through the admin routes) when given.
+ * Every action resolves to the group's new prompts, or null when the request failed.
+ */
+export function useAIPrompts(groupId?: string) {
+  const userApi = useUserApi();
+  const adminApi = useAdminApi();
+
+  const prompts = ref<AIPromptsOut | null>(null);
+  const loading = ref(false);
+
+  async function run(request: () => Promise<{ data: AIPromptsOut | null | undefined }>) {
+    loading.value = true;
+    try {
+      const response = await request();
+      if (!response.data) {
+        return null;
+      }
+
+      prompts.value = response.data;
+      return response.data;
+    }
+    catch {
+      return null;
+    }
+    finally {
+      loading.value = false;
+    }
+  }
+
+  function refresh() {
+    return run(() => groupId ? adminApi.aiProviders.getPrompts(groupId) : userApi.aiPrompts.getAll());
+  }
+
+  function save(name: string, payload: AIPromptUpdate) {
+    return run(() =>
+      groupId
+        ? adminApi.aiProviders.updatePrompt(groupId, name, payload)
+        : userApi.aiPrompts.updateOne(name, payload),
+    );
+  }
+
+  function reset(name: string) {
+    return run(() =>
+      groupId ? adminApi.aiProviders.deletePrompt(groupId, name) : userApi.aiPrompts.deleteOne(name),
+    );
+  }
+
+  return { prompts, loading, refresh, save, reset };
+}

