@@ -0,0 +1,153 @@
+"""
+Integration tests for per-group AI prompt customization.
+"""
+
+import pytest
+from fastapi.testclient import TestClient
+
+from mealie.db.db_setup import session_context
+from mealie.repos.repository_factory import AllRepositories
+from mealie.services.openai import OpenAIService
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+
+@pytest.fixture(autouse=True)
+def clean_overrides(unique_user: TestUser):
+    """unique_user outlives a single test, so start every test without customizations"""
+    with session_context() as session:
+        repos = AllRepositories(session, group_id=unique_user.group_id, household_id=None)
+        repos.group_ai_prompt_overrides.delete_many([o.id for o in repos.group_ai_prompt_overrides.get_all()])
+
+
+def _prompt(body: dict, name: str) -> dict:
+    return next(p for p in body["prompts"] if p["name"] == name)
+
+
+def test_get_prompts_lists_built_ins(api_client: TestClient, unique_user: TestUser):
+    response = api_client.get(api_routes.groups_ai_providers_prompts, headers=unique_user.token)
+    assert response.status_code == 200
+
+    body = response.json()
+    assert body["globalInstructions"] is None
+    assert [p["name"] for p in body["prompts"]] == OpenAIService.get_prompt_names()
+    assert "global" not in [p["name"] for p in body["prompts"]]
+    assert "system.compile-source" in [p["name"] for p in body["prompts"]]
+    assert _prompt(body, "system.compile-source")["isSystem"] is True
+    assert _prompt(body, "recipes.build-recipe")["isSystem"] is False
+    for prompt in body["prompts"]:
+        assert prompt["defaultContent"] == OpenAIService.get_default_prompt(prompt["name"])
+        assert prompt["mode"] is None
+        assert prompt["content"] is None
+        assert prompt["defaultChanged"] is False
+
+
+def test_put_prompt_replaces_existing_customization(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name("recipes.build-recipe")
+
+    response = api_client.put(url, json={"mode": "append", "content": "first"}, headers=unique_user.token)
+    assert response.status_code == 200
+    response = api_client.put(url, json={"mode": "override", "content": "second"}, headers=unique_user.token)
+    assert response.status_code == 200
+
+    prompt = _prompt(response.json(), "recipes.build-recipe")
+    assert prompt["mode"] == "override"
+    assert prompt["content"] == "second"
+    assert prompt["defaultChanged"] is False
+
+    with session_context() as session:
+        repos = AllRepositories(session, group_id=unique_user.group_id, household_id=None)
+        assert len(repos.group_ai_prompt_overrides.get_all()) == 1
+
+    response = api_client.delete(url, headers=unique_user.token)
+    assert response.status_code == 200
+    assert _prompt(response.json(), "recipes.build-recipe")["mode"] is None
+
+    # deleting a prompt that isn't customized is fine too
+    assert api_client.delete(url, headers=unique_user.token).status_code == 200
+
+
+def test_default_changed_flag(api_client: TestClient, unique_user: TestUser):
+    name = "recipes.build-recipe"
+    api_client.put(
+        api_routes.groups_ai_providers_prompts_prompt_name(name),
+        json={"mode": "override", "content": "mine"},
+        headers=unique_user.token,
+    )
+
+    with session_context() as session:
+        repos = AllRepositories(session, group_id=unique_user.group_id, household_id=None)
+        override = repos.group_ai_prompt_overrides.get_all()[0]
+        repos.group_ai_prompt_overrides.update(override.id, {"base_prompt_hash": "stale"})
+
+    response = api_client.get(api_routes.groups_ai_providers_prompts, headers=unique_user.token)
+    assert _prompt(response.json(), name)["defaultChanged"] is True
+
+
+def test_global_instructions(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name("global")
+
+    response = api_client.put(url, json={"mode": "append", "content": "use metric"}, headers=unique_user.token)
+    assert response.status_code == 200
+    assert response.json()["globalInstructions"] == "use metric"
+
+    assert api_client.put(url, json={"mode": "override", "content": "x"}, headers=unique_user.token).status_code == 400
+
+    response = api_client.delete(url, headers=unique_user.token)
+    assert response.json()["globalInstructions"] is None
+
+
+def test_blank_content_is_rejected(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name("recipes.build-recipe")
+    assert api_client.put(url, json={"mode": "append", "content": "   "}, headers=unique_user.token).status_code == 422
+
+
+@pytest.mark.parametrize("name", ["recipes.does-not-exist", "debug", "..secrets", "recipes.nope"])
+def test_unknown_prompt_names_are_not_found(api_client: TestClient, unique_user: TestUser, name: str):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(name)
+    assert api_client.put(url, json={"mode": "append", "content": "x"}, headers=unique_user.token).status_code == 404
+    assert api_client.delete(url, headers=unique_user.token).status_code == 404
+
+
+def test_prompt_routes_require_can_manage(api_client: TestClient, user_tuple: list[TestUser]):
+    usr, _ = user_tuple
+
+    user = usr.repos.users.get_one(usr.user_id)
+    assert user
+    user.can_manage = False
+    usr.repos.users.update(user.id, user)
+
+    url = api_routes.groups_ai_providers_prompts_prompt_name("global")
+    assert api_client.get(api_routes.groups_ai_providers_prompts, headers=usr.token).status_code == 403
+    assert api_client.put(url, json={"mode": "append", "content": "x"}, headers=usr.token).status_code == 403
+    assert api_client.delete(url, headers=usr.token).status_code == 403
+
+
+def test_admin_routes_and_group_isolation(api_client: TestClient, admin_user: TestUser, unique_user: TestUser):
+    url = api_routes.admin_groups_group_id_ai_providers_prompts_prompt_name(unique_user.group_id, "global")
+    response = api_client.put(url, json={"mode": "append", "content": "G"}, headers=admin_user.token)
+    assert response.status_code == 200
+    assert response.json()["globalInstructions"] == "G"
+
+    assert api_client.put(url, json={"mode": "append", "content": "G"}, headers=unique_user.token).status_code == 403
+    assert (
+        api_client.get(
+            api_routes.admin_groups_group_id_ai_providers_prompts(unique_user.group_id), headers=unique_user.token
+        ).status_code
+        == 403
+    )
+
+    with session_context() as session:
+        repos = AllRepositories(session, group_id=unique_user.group_id, household_id=None)
+        assert [o.content for o in repos.group_ai_prompt_overrides.get_all()] == ["G"]
+        assert "G" in OpenAIService(repos).get_prompt("recipes.build-recipe")
+
+        other = AllRepositories(session, group_id=admin_user.group_id, household_id=None)
+        assert other.group_ai_prompt_overrides.get_all() == []
+
+    assert (
+        api_client.get(
+            api_routes.admin_groups_group_id_ai_providers_prompts(unique_user.group_id), headers=admin_user.token
+        ).json()["globalInstructions"]
+        == "G"
+    )
