@@ -0,0 +1,105 @@
+from pathlib import Path
+
+import pytest
+import sqlalchemy as sa
+from alembic.migration import MigrationContext
+from alembic.operations import Operations
+
+from mealie.services.openai import OpenAIService
+from tests.utils.alembic_reader import ALEMBIC_MIGRATIONS, import_file
+
+SETTINGS_IDS = ["a" * 32, "b" * 32]
+
+
+def _migration():
+    path = next(ALEMBIC_MIGRATIONS.glob("*a91720b8a7e7*.py"))
+    return import_file("add_ai_prompt_overrides", path)
+
+
+def _upgrade(connection: sa.Connection) -> None:
+    with Operations.context(MigrationContext.configure(connection)):
+        _migration().upgrade()
+
+
+@pytest.fixture()
+def engine():
+    """A bare SQLite database holding nothing but an ai_provider_settings table"""
+    engine = sa.create_engine("sqlite://")
+    try:
+        with engine.begin() as connection:
+            connection.execute(sa.text("CREATE TABLE ai_provider_settings (id CHAR(32) PRIMARY KEY)"))
+            for settings_id in SETTINGS_IDS:
+                connection.execute(sa.text("INSERT INTO ai_provider_settings (id) VALUES (:id)"), {"id": settings_id})
+        yield engine
+    finally:
+        engine.dispose()
+
+
+def _write(root: Path, relative: str, content: str) -> None:
+    path = root / relative
+    path.parent.mkdir(parents=True, exist_ok=True)
+    path.write_text(content)
+
+
+def test_migration_follows_current_head():
+    migration = _migration()
+    assert migration.revision == "a91720b8a7e7"
+    assert migration.down_revision == "1e69ea7cd45e"
+
+
+def test_upgrade_without_legacy_dir_only_creates_table(engine, monkeypatch):
+    monkeypatch.delenv("OPENAI_CUSTOM_PROMPT_DIR", raising=False)
+    with engine.connect() as connection:
+        _upgrade(connection)
+        assert sa.inspect(connection).has_table("ai_prompt_overrides")
+        assert connection.execute(sa.text("SELECT COUNT(*) FROM ai_prompt_overrides")).scalar_one() == 0
+
+
+def test_upgrade_ignores_legacy_dir_that_is_not_a_directory(engine, monkeypatch, tmp_path):
+    monkeypatch.setenv("OPENAI_CUSTOM_PROMPT_DIR", str(tmp_path / "missing"))
+    with engine.connect() as connection:
+        _upgrade(connection)
+        assert connection.execute(sa.text("SELECT COUNT(*) FROM ai_prompt_overrides")).scalar_one() == 0
+
+
+def test_upgrade_imports_legacy_prompts_for_every_settings_row(engine, monkeypatch, tmp_path):
+    _write(tmp_path, "recipes/build-recipe.txt", "  MY BUILD \n")
+    _write(tmp_path, "recipes/translate-recipe.txt", "   \n")
+    _write(tmp_path, "recipes/compile-source.txt", "MY COMPILE")
+    _write(tmp_path, "general/transcribe-audio.txt", "MY AUDIO")
+    _write(tmp_path, "general/debug.txt", "MY DEBUG")
+    _write(tmp_path, "recipes/scrape-recipe.txt", "REMOVED")
+    monkeypatch.setenv("OPENAI_CUSTOM_PROMPT_DIR", str(tmp_path))
+
+    with engine.connect() as connection:
+        _upgrade(connection)
+        rows = connection.execute(
+            sa.text("SELECT id, settings_id, name, mode, content, base_prompt_hash FROM ai_prompt_overrides")
+        ).all()
+
+    expected = {
+        "recipes.build-recipe": "  MY BUILD \n",
+        "system.compile-source": "MY COMPILE",
+        "system.transcribe-audio": "MY AUDIO",
+    }
+    assert len(rows) == len(expected) * len(SETTINGS_IDS)
+    assert len({row.id for row in rows}) == len(rows)
+    for row in rows:
+        assert row.settings_id in SETTINGS_IDS
+        assert row.mode == "override"
+        assert row.content == expected[row.name]
+        assert row.base_prompt_hash == OpenAIService._hash_prompt(OpenAIService.get_default_prompt(row.name))
+
+
+def test_downgrade_drops_table(engine, monkeypatch):
+    monkeypatch.delenv("OPENAI_CUSTOM_PROMPT_DIR", raising=False)
+    with engine.connect() as connection:
+        _upgrade(connection)
+        with Operations.context(MigrationContext.configure(connection)):
+            _migration().downgrade()
+        assert not sa.inspect(connection).has_table("ai_prompt_overrides")
+
+
+@pytest.mark.parametrize("name", OpenAIService.get_prompt_names())
+def test_built_in_prompts_load(name: str):
+    assert OpenAIService.get_default_prompt(name)
