+
+<script setup lang="ts">
+import { useAIPrompts } from "~/composables/use-ai-providers";
+import { alert } from "~/composables/use-toast";
+import type { AIPromptsOut } from "~/lib/api/types/group";
+
+type PromptMode = "default" | "append" | "override";
+
+interface PromptState {
+  name: string;
+  isSystem: boolean;
+  defaultContent: string;
+  defaultChanged: boolean;
+  // what is saved
+  savedMode: PromptMode;
+  savedContent: string;
+  // what is being edited; the append and override editors each keep their own text
+  mode: PromptMode;
+  append: string;
+  override: string;
+}
+
+const props = defineProps({
+  groupId: {
+    type: String,
+    default: undefined,
+  },
+});
+
+const i18n = useI18n();
+const { prompts, refresh, save, reset } = useAIPrompts(props.groupId);
+
+const states = ref<PromptState[]>([]);
+const globalText = ref("");
+const savedGlobal = ref("");
+
+function buildState(prompt: AIPromptsOut["prompts"][number]): PromptState {
+  const mode: PromptMode = prompt.mode ?? "default";
+  const content = prompt.content ?? "";
+  return {
+    name: prompt.name,
+    isSystem: prompt.isSystem,
+    defaultContent: prompt.defaultContent,
+    defaultChanged: !!prompt.defaultChanged,
+    savedMode: mode,
+    savedContent: mode === "default" ? "" : content,
+    mode,
+    append: mode === "append" ? content : "",
+    override: mode === "override" ? content : "",
+  };
+}
+
+// Build the editor state once the prompts are available; later updates of the ref (after a save) must not
+// overwrite what the user is still editing in other sections.
+watch(
+  prompts,
+  (value) => {
+    if (!value) {
+      return;
+    }
+
+    if (!states.value.length) {
+      states.value = value.prompts.map(buildState);
+      globalText.value = value.globalInstructions ?? "";
+      savedGlobal.value = globalText.value;
+    }
+  },
+  { immediate: true },
+);
+
+onMounted(() => {
+  refresh();
+});
+
+function editedContent(state: PromptState): string {
+  return state.mode === "append" ? state.append : state.override;
+}
+
+function isDirty(state: PromptState): boolean {
+  if (state.mode !== state.savedMode) {
+    return true;
+  }
+  return state.mode !== "default" && editedContent(state) !== state.savedContent;
+}
+
+const globalDirty = computed(() => globalText.value !== savedGlobal.value);
+
+function setMode(state: PromptState, mode: PromptMode | undefined) {
+  if (!mode) {
+    return;
+  }
+
+  if (mode === "override" && !state.override) {
+    state.override = state.defaultContent;
+  }
+  state.mode = mode;
+}
+
+function notify(result: AIPromptsOut | null) {
+  if (result) {
+    alert.success(i18n.t("group.ai-prompts.saved"));
+  }
+  else {
+    alert.error(i18n.t("group.ai-prompts.save-failed"));
+  }
+}
+
+async function savePrompt(state: PromptState) {
+  const mode = state.mode;
+  const content = mode === "default" ? "" : editedContent(state);
+
+  const result = mode === "default" ? await reset(state.name) : await save(state.name, { mode, content });
+  notify(result);
+  if (!result) {
+    return;
+  }
+
+  state.savedMode = mode;
+  state.savedContent = content;
+  const updated = result.prompts?.find(p => p.name === state.name);
+  if (updated) {
+    state.defaultChanged = !!updated.defaultChanged;
+  }
+}
+
+async function saveGlobal() {
+  const content = globalText.value.trim();
+
+  const result = content ? await save("global", { mode: "append", content }) : await reset("global");
+  notify(result);
+  if (!result) {
+    return;
+  }
+
+  globalText.value = content;
+  savedGlobal.value = content;
+}
+</script>
