+
+/**
+ * A group's prompt customizations. Pass a groupId to manage another group's prompts as an admin,
+ * otherwise the current user's group is used. Every call resolves to the group's new prompts,
+ * or to null when the request failed.
+ */
+export function useAIPrompts(groupId?: string) {
+  const userApi = useUserApi();
+  const adminApi = groupId ? useAdminApi() : null;
+
+  const prompts = ref<AIPromptsOut | null>(null);
+  const loading = ref(false);
+
+  async function run(request: () => Promise<{ data: AIPromptsOut | null }>) {
+    loading.value = true;
+    try {
+      const { data } = await request();
+      if (data) {
+        prompts.value = data;
+      }
+      return data ?? null;
+    }
+    catch {
+      return null;
+    }
+    finally {
+      loading.value = false;
+    }
+  }
+
+  function refresh() {
+    return run(() => (adminApi && groupId ? adminApi.aiProviders.getPrompts(groupId) : userApi.aiProviders.getPrompts()));
+  }
+
+  function save(name: string, payload: { mode: AIPromptMode; content: string }) {
+    return run(() =>
+      adminApi && groupId
+        ? adminApi.aiProviders.setPrompt(groupId, name, payload)
+        : userApi.aiProviders.setPrompt(name, payload),
+    );
+  }
+
+  function reset(name: string) {
+    return run(() =>
+      adminApi && groupId ? adminApi.aiProviders.resetPrompt(groupId, name) : userApi.aiProviders.resetPrompt(name),
+    );
+  }
+
+  return { prompts, loading, refresh, save, reset };
+}
