+"""
+Integration tests for per-group AI prompt customization.
+"""
+
+import pytest
+from fastapi.testclient import TestClient
+
+from mealie.services.openai import OpenAIService
+from mealie.services.openai.openai import GLOBAL_PROMPT_NAME
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+PROMPT = "recipes.build-recipe"
+
+
+def _prompt(body: dict, name: str = PROMPT) -> dict:
+    return next(p for p in body["prompts"] if p["name"] == name)
+
+
+def test_get_prompts_lists_built_in_prompts(api_client: TestClient, unique_user: TestUser):
+    response = api_client.get(api_routes.groups_ai_providers_prompts, headers=unique_user.token)
+    assert response.status_code == 200
+
+    body = response.json()
+    assert body["globalInstructions"] is None
+    assert [p["name"] for p in body["prompts"]] == OpenAIService.get_prompt_names()
+    assert GLOBAL_PROMPT_NAME not in [p["name"] for p in body["prompts"]]
+
+    prompt = _prompt(body)
+    assert prompt["defaultContent"] == OpenAIService.get_default_prompt(PROMPT)
+    assert prompt["isSystem"] is False
+    assert prompt["mode"] is None
+    assert prompt["content"] is None
+    assert prompt["defaultChanged"] is False
+    assert _prompt(body, "system.compile-source")["isSystem"] is True
+
+
+def test_put_prompt_replaces_existing_customization(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(PROMPT)
+    for mode, content in [("append", "first"), ("override", "second")]:
+        response = api_client.put(url, json={"mode": mode, "content": content}, headers=unique_user.token)
+        assert response.status_code == 200
+
+    prompt = _prompt(response.json())
+    assert (prompt["mode"], prompt["content"], prompt["defaultChanged"]) == ("override", "second", False)
+
+    stored = unique_user.repos.group_ai_prompt_overrides.get_all()
+    assert len(stored) == 1
+    assert OpenAIService(unique_user.repos).get_prompt(PROMPT) == "second"
+
+
+def test_default_changed_flags_stale_override(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(PROMPT)
+    api_client.put(url, json={"mode": "override", "content": "mine"}, headers=unique_user.token)
+
+    stored = unique_user.repos.group_ai_prompt_overrides.get_all()[0]
+    unique_user.repos.group_ai_prompt_overrides.update(stored.id, {"base_prompt_hash": "stale"})
+
+    body = api_client.get(api_routes.groups_ai_providers_prompts, headers=unique_user.token).json()
+    assert _prompt(body)["defaultChanged"] is True
+
+
+def test_global_instructions(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(GLOBAL_PROMPT_NAME)
+
+    response = api_client.put(url, json={"mode": "override", "content": "G"}, headers=unique_user.token)
+    assert response.status_code == 400
+
+    response = api_client.put(url, json={"mode": "append", "content": "G"}, headers=unique_user.token)
+    assert response.status_code == 200
+    assert response.json()["globalInstructions"] == "G"
+    assert OpenAIService(unique_user.repos).get_prompt(PROMPT).endswith("\nG")
+
+    response = api_client.delete(url, headers=unique_user.token)
+    assert response.status_code == 200
+    assert response.json()["globalInstructions"] is None
+
+
+def test_put_blank_prompt_is_rejected(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(PROMPT)
+    response = api_client.put(url, json={"mode": "append", "content": "   "}, headers=unique_user.token)
+    assert response.status_code == 422
+
+
+def test_delete_prompt_resets_it(api_client: TestClient, unique_user: TestUser):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(PROMPT)
+    api_client.put(url, json={"mode": "append", "content": "extra"}, headers=unique_user.token)
+
+    for _ in range(2):  # deleting an uncustomized prompt is fine too
+        response = api_client.delete(url, headers=unique_user.token)
+        assert response.status_code == 200
+        assert _prompt(response.json())["mode"] is None
+
+    assert unique_user.repos.group_ai_prompt_overrides.get_all() == []
+
+
+@pytest.mark.parametrize("name", ["recipes.does-not-exist", "debug", "..secrets", "recipes.nope"])
+def test_unknown_prompt_names_are_not_found(api_client: TestClient, unique_user: TestUser, name: str):
+    url = api_routes.groups_ai_providers_prompts_prompt_name(name)
+    assert api_client.put(url, json={"mode": "append", "content": "x"}, headers=unique_user.token).status_code == 404
+    assert api_client.delete(url, headers=unique_user.token).status_code == 404
+
+
+def test_admin_prompts_apply_to_the_target_group(api_client: TestClient, admin_user: TestUser, unique_user: TestUser):
+    group_id = unique_user.group_id
+    url = api_routes.admin_groups_group_id_ai_providers_prompts_prompt_name(group_id, PROMPT)
+
+    assert api_client.put(url, json={"mode": "override", "content": "mine"}, headers=unique_user.token).status_code == 403
+
+    response = api_client.put(url, json={"mode": "override", "content": "mine"}, headers=admin_user.token)
+    assert response.status_code == 200
+    assert _prompt(response.json())["content"] == "mine"
+    assert OpenAIService(unique_user.repos).get_prompt(PROMPT) == "mine"
+    # other groups are untouched
+    assert admin_user.repos.group_ai_prompt_overrides.get_all() == []
+
+    listing = api_routes.admin_groups_group_id_ai_providers_prompts(group_id)
+    assert api_client.get(listing, headers=unique_user.token).status_code == 403
+    assert api_client.get(listing, headers=admin_user.token).status_code == 200
+
+    response = api_client.delete(url, headers=admin_user.token)
+    assert response.status_code == 200
+    assert _prompt(response.json())["mode"] is None
